INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('fb642da4-0ed2-49f7-812d-35d99ba9229a', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'component', 'avatar', 'Avatar', 'Data Display', NULL, 'mdi-account-circle', 'components.catalog.avatar.description', 'Circular or rounded media container for user images, icons or initials text.', NULL, NULL, 'origam-avatar', NULL, 'packages/ds/src/components/Avatar/OrigamAvatar.vue', 'origam', NULL, NULL, '/stories/?story=components-avatar--design', '/docs/components/Avatar/OrigamAvatar.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.avatar.a11y.alt_note", "noteFallback": "When using the image prop, pass an ISrcObject with an alt property to provide a text alternative for screen readers. Plain string URLs result in an empty alt."}, {"noteKey": "components.avatar.a11y.icon_note", "noteFallback": "Icon-only avatars should be wrapped in a container with an accessible label (e.g. aria-label on the parent) when they convey meaning."}, {"noteKey": "components.avatar.a11y.interactive_note", "noteFallback": "When active=true or the avatar is used in an interactive context (click handlers), wrap it in a button or add role=\"button\" with a keyboard handler."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-avatar---background-color", "descriptionKey": "components.avatar.tokens.background_color", "descriptionFallback": "Default avatar background (when no image)."}, {"type": "dimension", "value": "var(--origam-radius---full)", "tokenPath": "--origam-avatar---border-radius", 