"round-robin"}], "labelKey": "components.bracket.playground.variant", "defaultValue": "single-elimination", "labelFallback": "Variant"}, {"kind": "select", "prop": "direction", "options": [{"label": "horizontal", "value": "horizontal"}, {"label": "vertical", "value": "vertical"}], "labelKey": "components.bracket.playground.direction", "defaultValue": "horizontal", "labelFallback": "Direction"}, {"kind": "switch", "prop": "showRoundTitles", "labelKey": "components.bracket.playground.show_round_titles", "defaultValue": true, "labelFallback": "Show round titles"}, {"kind": "switch", "prop": "showScores", "labelKey": "components.bracket.playground.show_scores", "defaultValue": true, "labelFallback": "Show scores"}, {"kind": "switch", "prop": "showSeed", "labelKey": "components.bracket.playground.show_seed", "defaultValue": false, "labelFallback": "Show seed"}, {"kind": "switch", "prop": "interactive", "labelKey": "components.bracket.playground.interactive", "defaultValue": true, "labelFallback": "Interactive"}]}, "previewVariants": [{"label": "single-elimination", "props": {"variant": "single-elimination"}}, {"label": "round-robin", "props": {"variant": "round-robin"}}, {"label": "with scores", "props": {"variant": "single-elimination", "showSeed": true, "showScores": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
