INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1602ce5d-eb8a-4736-83b0-99f09b784042', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'component', 'card-header', 'CardHeader', 'Surface', NULL, 'mdi-card-text-outline', 'components.catalog.card_header.description', 'Card header section rendering title, subtitle and optional prepend/append icon or avatar in a 3-column grid layout.', NULL, NULL, 'origam-card-header', NULL, 'packages/ds/src/components/Card/OrigamCardHeader.vue', 'origam', NULL, NULL, '/stories/?story=components-card--design', '/docs/components/Card/OrigamCard.html', 'card', '{"a11y": {"notes": [{"noteKey": "components.card_header.a11y.heading", "noteFallback": "The title prop is rendered as plain text in a <div>. If the card header serves as a section heading, wrap the title slot content in the appropriate heading element (<h2>, <h3>, etc.) for correct document outline."}, {"noteKey": "components.card_header.a11y.append_label", "noteFallback": "When appendIcon is an action (e.g. a menu trigger), add aria-label via the #append slot or on the wrapping element to describe the action to screen reader users."}], "roles": [], "keyboard": [{"key": "Tab", "actionKey": "components.card_header.a11y.key_tab", "actionFallback": "Moves focus to interactive elements inside the header (prepend/append clicks)."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"140\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"100\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"100\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"6 3\" opacity=\"0.5\"/>\n  <rect x=\"30\" y=\"30\" width=\"60\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"60\" y=\"73\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">prepend</text>\n  <rect x=\"100\" y=\"30\" width=\"480\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"110\" y=\"38\" width=\"460\" height=\"24\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.10))\"/>\n  <text x=\"340\" y=\"54\" font-size=\"12\" fill=\"var(--origam-color__text---primary, #1a0533)\" text-anchor=\"middle\" font-family=\"sans-serif\" font-weight=\"600\">Title</text>\n  <rect x=\"110\" y=\"66\" width=\"460\" height=\"18\" rx=\"2\" fill=\"rgba(124,58,237,0.04)\"/>\n  <text x=\"340\" y=\"79\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\" opacity=\"0.7\">Subtitle</text>\n  <rect x=\"590\" y=\"30\" width=\"60\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"620\" y=\"73\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">append</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"38\" cy=\"32\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"38\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"38\" cy=\"22\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"38\" y=\"26.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"108\" cy=\"32\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"108\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"118\" cy=\"40\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"118\" y=\"44.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"118\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"118\" y=\"72.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n", "code": "<!-- root: OrigamToolbar with overrides -->\n<component :is=\"tag\" class=\"origam-card-header\">\n  <!-- absolute underlay layer -->\n  <span class=\"origam-card-header__underlay\" />\n  <slot name=\"wrapper\">\n    <!-- prepend: avatar or icon -->\n    <div class=\"origam-card-header__prepend\">\n      <slot name=\"prepend\">\n        <origam-avatar v-if=\"prependAvatar\" :image=\"prependAvatar\" />\n        <origam-icon v-if=\"prependIcon\" :icon=\"prependIcon\" />\n      </slot>\n    </div>\n    <!-- content: title + subtitle + default slot -->\n    <div class=\"origam-card-header__content\">\n      <div class=\"origam-card-header__title\">\n        <slot name=\"title\">{{ title }}</slot>\n      </div>\n      <div class=\"origam-card-header__subtitle\">\n        <slot name=\"subtitle\">{{ subtitle }}</slot>\n      </div>\n      <slot name=\"default\" />\n    </div>\n    <!-- append: avatar or icon -->\n    <div class=\"origam-card-header__append\">\n      <slot name=\"append\">\n        <origam-avatar v-if=\"appendAvatar\" :image=\"appendAvatar\" />\n        <origam-icon v-if=\"appendIcon\" :icon=\"appendIcon\" />\n      </slot>\n    </div>\n  </slot>\n</component>", "legend": [{"cls": ".origam-card-header", "num": 1, "descriptionKey": "components.card_header.anatomy.root", "descriptionFallback": "Root element (renders as OrigamToolbar). 3-column grid: <code>max-content 1fr auto</code>. Overrides toolbar box-shadow and background to be transparent/none to match the card surface."}, {"cls": ".origam-card-header__underlay", "num": 2, "descriptionKey": "components.card_header.anatomy.underlay", "descriptionFallback": "Absolute positioned underlay span. Reserved for interaction overlays (position: absolute, inset: 0)."}, {"cls": ".origam-card-header__prepend", "num": 3, "descriptionKey": "components.card_header.anatomy.prepend", "descriptionFallback": "Prepend column host (grid-area: prepend). Display: flex, align-items: center. Renders prependAvatar, prependIcon or #prepend slot."}, {"cls": ".origam-card-header__content", "num": 4, "descriptionKey": "components.card_header.anatomy.content", "descriptionFallback": "Content column host (grid-area: content). overflow: hidden. Contains title, subtitle and the #default slot."}, {"cls": ".origam-card-header__title", "num": 5, "descriptionKey": "components.card_header.anatomy.title", "descriptionFallback": "Title text block. font-size: 1rem, font-weight: 400, white-space: nowrap, overflow: hidden, text-overflow: ellipsis."}, {"cls": ".origam-card-header__subtitle", "num": 6, "descriptionKey": "components.card_header.anatomy.subtitle", "descriptionFallback": "Subtitle text block. opacity: 0.6, font-size: 0.875rem. Line-clamped via -webkit-box-orient: vertical."}], "classes": [{"cls": "origam-card-header", "descriptionKey": "components.card_header.anatomy.root", "descriptionFallback": "Root element. display: grid, 3-column layout, min-height: 40px (density-adjusted)."}, {"cls": "origam-card-header__underlay", "descriptionKey": "components.card_header.anatomy.underlay", "descriptionFallback": "Absolute overlay/underlay reserved for interaction feedback."}, {"cls": "origam-card-header__prepend", "descriptionKey": "components.card_header.anatomy.prepend", "descriptionFallback": "Leading icon/avatar column."}, {"cls": "origam-card-header__content", "descriptionKey": "components.card_header.anatomy.content", "descriptionFallback": "Center text column. overflow: hidden."}, {"cls": "origam-card-header__title", "descriptionKey": "components.card_header.anatomy.title", "descriptionFallback": "Title text block with ellipsis truncation."}, {"cls": "origam-card-header__subtitle", "descriptionKey": "components.card_header.anatomy.subtitle", "descriptionFallback": "Subtitle text block at 0.6 opacity."}, {"cls": "origam-card-header__append", "descriptionKey": "components.card_header.anatomy.append", "descriptionFallback": "Trailing icon/avatar column."}], "svgDesc": "Schematic of the CardHeader component with 6 numbered internal parts.", "svgTitle": "Anatomy of OrigamCardHeader", "rootClass": "origam-card-header", "figcaption": "Anatomy of <code>&lt;origam-card-header&gt;</code> — root grid ① (3-column: prepend / content / append), underlay ② (absolute), prepend ③, content area ④, title ⑤, subtitle ⑥.", "svgViewBox": "0 0 700 140"}, "cssVars": [{"name": "--origam-card-header---min-height", "defaultValue": "40px", "descriptionKey": "components.card_header.css_vars.min_height", "descriptionFallback": "Minimum height of the header. Adjusted with density offset."}, {"name": "--origam-card-header---padding-block-start", "defaultValue": "8px", "descriptionKey": "components.card_header.css_vars.padding_block_start", "descriptionFallback": "Block-start padding (density-adjusted at render time)."}, {"name": "--origam-card-header---padding-block-end", "defaultValue": "8px", "descriptionKey": "components.card_header.css_vars.padding_block_end", "descriptionFallback": "Block-end padding (density-adjusted)."}, {"name": "--origam-card-header---padding-inline-start", "defaultValue": "16px", "descriptionKey": "components.card_header.css_vars.padding_inline_start", "descriptionFallback": "Inline-start padding (density-adjusted)."}, {"name": "--origam-card-header---padding-inline-end", "defaultValue": "16px", "descriptionKey": "components.card_header.css_vars.padding_inline_end", "descriptionFallback": "Inline-end padding (density-adjusted)."}, {"name": "--origam-card-header---density", "defaultValue": "0px", "descriptionKey": "components.card_header.css_vars.density", "descriptionFallback": "Density offset added to padding values. compact: −8px, default: 0px, comfortable: +8px."}, {"name": "--origam-card-header---grid-template-areas", "defaultValue": "\"prepend content append\"", "descriptionKey": "components.card_header.css_vars.grid_template_areas", "descriptionFallback": "Grid layout areas: prepend / content / append."}, {"name": "--origam-card-header---grid-template-columns", "defaultValue": "max-content 1fr auto", "descriptionKey": "components.card_header.css_vars.grid_template_columns", "descriptionFallback": "Grid columns: prepend (shrink-to-content) / content (fill) / append (auto)."}, {"name": "--origam-card-header__title---font-size", "defaultValue": "1rem", "descriptionKey": "components.card_header.css_vars.title_font_size", "descriptionFallback": "Title font size (1rem = 16px)."}, {"name": "--origam-card-header__subtitle---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.card_header.css_vars.subtitle_font_size", "descriptionFallback": "Subtitle font size (0.875rem = 14px)."}, {"name": "--origam-card-header__subtitle---opacity", "defaultValue": "0.6", "descriptionKey": "components.card_header.css_vars.subtitle_opacity", "descriptionFallback": "Subtitle opacity (reduced to create visual hierarchy)."}, {"name": "--origam-card-header__icon---opacity", "defaultValue": "0.87", "descriptionKey": "components.card_header.css_vars.icon_opacity", "descriptionFallback": "Opacity applied to icons in the prepend/append areas."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.card_header.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.card_header.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed cardHeaderStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.card_header.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.card_header.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.card_header.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.card_header.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.card_header.playground.title", "defaultValue": "Card Title", "labelFallback": "Title"}, {"kind": "text", "prop": "subtitle", "labelKey": "components.card_header.playground.subtitle", "defaultValue": "Supporting text", "labelFallback": "Subtitle"}, {"kind": "select", "prop": "prependIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-account-circle", "value": "mdi-account-circle"}, {"label": "mdi-star", "value": "mdi-star"}, {"label": "mdi-image", "value": "mdi-image"}], "labelKey": "components.card_header.playground.prepend_icon", "defaultValue": "", "labelFallback": "Prepend icon"}, {"kind": "select", "prop": "appendIcon", "options": [{"label": "(none)", "value": ""}, {"label": "mdi-dots-vertical", "value": "mdi-dots-vertical"}, {"label": "mdi-close", "value": "mdi-close"}, {"label": "mdi-share-variant", "value": "mdi-share-variant"}], "labelKey": "components.card_header.playground.append_icon", "defaultValue": "", "labelFallback": "Append icon"}, {"kind": "select", "prop": "density", "options": [{"label": "comfortable", "value": "comfortable"}, {"label": "default", "value": "default"}, {"label": "compact", "value": "compact"}], "labelKey": "components.card_header.playground.density", "defaultValue": "default", "labelFallback": "Density"}]}, "previewVariants": [{"label": "title only", "props": {"title": "Card Title"}}, {"label": "with subtitle", "props": {"title": "Card Title", "subtitle": "Supporting text here"}}, {"label": "with prepend icon", "props": {"title": "Profile", "subtitle": "Account", "prependIcon": "mdi-account-circle"}}, {"label": "with append icon", "props": {"title": "Settings", "appendIcon": "mdi-dots-vertical"}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('2568b23f-bf2e-4b09-bd6a-167fc94c841e', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'component', 'card-text', 'CardText', 'Surface', NULL, 'mdi-text-long', 'components.catalog.card_text.description', 'Card body text section. A flex-grow container with density-aware padding and body typography defaults.', NULL, NULL, 'origam-card-text', NULL, 'packages/ds/src/components/Card/OrigamCardText.vue', 'origam', NULL, NULL, '/stories/?story=components-card--design', '/docs/components/Card/OrigamCard.html', 'card', '{"a11y": {"notes": [{"noteKey": "components.card_text.a11y.semantics", "noteFallback": "OrigamCardText renders as a <div> by default. When the content is a paragraph of text, consider passing tag=\"p\" or wrapping inner content in <p> tags for correct semantics. Avoid placing block-level elements inside a <p> tag if you change the root tag."}, {"noteKey": "components.card_text.a11y.focus", "noteFallback": "CardText is not interactive and does not receive focus. Interactive elements inside the text (links, buttons) manage their own focus and keyboard interaction."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"600\" height=\"120\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"560\" height=\"80\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"36\" y=\"34\" width=\"528\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"300\" y=\"58\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"sans-serif\">Body text or #default slot content</text>\n  <text x=\"300\" y=\"74\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"sans-serif\" opacity=\"0.7\">font-size: 0.875rem · flex: 1 1 auto</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"44\" cy=\"36\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"44\" y=\"40.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"38\" y1=\"26\" x2=\"90\" y2=\"8\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"94\" y=\"6\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-card-text</text>\n", "code": "<!-- root: <div> by default, customisable via tag prop -->\n<div class=\"origam-card-text\">\n  <slot name=\"default\">\n    <span>{{ text }}</span>\n  </slot>\n</div>", "legend": [{"cls": ".origam-card-text", "num": 1, "descriptionKey": "components.card_text.anatomy.root", "descriptionFallback": "Root element (default: <code>&lt;div&gt;</code>). flex: 1 1 auto so it fills available card height. font-size: 0.875rem, font-weight: 400. Padding is density-adjusted."}, {"cls": "(content / #default slot)", "num": 2, "descriptionKey": "components.card_text.anatomy.content", "descriptionFallback": "Inner content: renders <code>&lt;span&gt;{{ text }}&lt;/span&gt;</code> when the text prop is provided, or the #default slot for richer content."}], "classes": [{"cls": "origam-card-text", "descriptionKey": "components.card_text.anatomy.root", "descriptionFallback": "Root element. flex: 1 1 auto, body typography, density-aware padding on all sides."}, {"cls": "origam-card-text--density-default", "descriptionKey": "components.card_text.anatomy.density_default", "descriptionFallback": "Density default (0px offset)."}, {"cls": "origam-card-text--density-compact", "descriptionKey": "components.card_text.anatomy.density_compact", "descriptionFallback": "Density compact (−8px offset on all padding sides)."}, {"cls": "origam-card-text--density-comfortable", "descriptionKey": "components.card_text.anatomy.density_comfortable", "descriptionFallback": "Density comfortable (+8px offset on all padding sides)."}], "svgDesc": "Schematic of the CardText component with 2 numbered parts.", "svgTitle": "Anatomy of OrigamCardText", "rootClass": "origam-card-text", "figcaption": "Anatomy of <code>&lt;origam-card-text&gt;</code> — root container ① (flex: 1 1 auto) with density-aware padding ② wrapping the body text or <code>#default</code> slot.", "svgViewBox": "0 0 600 120"}, "cssVars": [{"name": "--origam-card-text---flex", "defaultValue": "1 1 auto", "descriptionKey": "components.card_text.css_vars.flex", "descriptionFallback": "Flex grow/shrink/basis for the text area. 1 1 auto ensures it fills available vertical space."}, {"name": "--origam-card-text---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.card_text.css_vars.font_size", "descriptionFallback": "Body text font size (0.875rem = 14px)."}, {"name": "--origam-card-text---font-weight", "defaultValue": "400", "descriptionKey": "components.card_text.css_vars.font_weight", "descriptionFallback": "Body text font weight (normal)."}, {"name": "--origam-card-text---letter-spacing", "defaultValue": "0.0178571429em", "descriptionKey": "components.card_text.css_vars.letter_spacing", 