INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a987a1a3-08f7-4025-ad05-5a70b738b771', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'component', 'chart-bullet', 'ChartBullet', 'Data Display', NULL, 'mdi-speedometer', 'components.catalog.chart_bullet.description', 'Bullet chart (Stephen Few design) — compact KPI display combining qualitative range bands, an actual-value bar, and a target marker tick. Supports horizontal and vertical orientations.', NULL, NULL, 'origam-chart-bullet', NULL, 'packages/ds/src/components/Chart/OrigamChartBullet.vue', 'origam', NULL, NULL, '/stories/?story=components-chart-bullet--design', '/docs/components/Chart/OrigamChartBullet.html', 'chart', '{"a11y": {"notes": [{"noteKey": "components.chart_bullet.a11y.figure_role", "noteFallback": "Root has role=\"figure\" with aria-label from the title prop (falls back to \"bullet chart\")."}, {"noteKey": "components.chart_bullet.a11y.svg_role", "noteFallback": "The SVG carries role=\"img\" with a <title> and <desc> for screen readers."}, {"noteKey": "components.chart_bullet.a11y.bar_aria", "noteFallback": "Each bullet bar has aria-label describing category, value, target and achievement percentage."}, {"noteKey": "components.chart_bullet.a11y.reduced_motion", "noteFallback": "Entry animations are disabled via @media (prefers-reduced-motion: reduce)."}], "roles": ["figure", "img", "button"], "keyboard": [{"key": "Tab", "actionKey": "components.chart_bullet.a11y.key_tab", "actionFallback": "Moves focus through each bullet bar (tabindex=\"0\") and legend items."}, {"key": "Enter / Space", "actionKey": "components.chart_bullet.a11y.key_activate", "actionFallback": "Activates the focused bullet bar, firing the point-click emit."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"260\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"20\" width=\"660\" height=\"220\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"32\" y=\"30\" width=\"636\" height=\"20\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\"/>\n  <text x=\"350\" y=\"44\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__header (title + subtitle)</text>\n  <rect x=\"140\" y=\"62\" width=\"480\" height=\"22\" rx=\"2\" fill=\"rgba(239,68,68,0.25)\"/>\n  <rect x=\"140\" y=\"62\" width=\"200\" height=\"22\" rx=\"2\" fill=\"rgba(234,179,8,0.35)\"/>\n  <rect x=\"140\" y=\"62\" width=\"340\" height=\"22\" rx=\"2\" fill=\"rgba(34,197,94,0.30)\"/>\n  <rect x=\"140\" y=\"67\" width=\"260\" height=\"12\" rx=\"1\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.85\"/>\n  <line x1=\"400\" y1=\"56\" x2=\"400\" y2=\"88\" stroke=\"var(--origam-color__feedback--danger---bg, #ef4444)\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n  <text x=\"32\" y=\"77\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\" text-anchor=\"end\">Revenue</text>\n  <rect x=\"140\" y=\"100\" width=\"480\" height=\"22\" rx=\"2\" fill=\"rgba(239,68,68,0.25)\"/>\n  <rect x=\"140\" y=\"100\" width=\"200\" height=\"22\" rx=\"2\" fill=\"rgba(234,179,8,0.35)\"/>\n  <rect x=\"140\" y=\"100\" width=\"340\" height=\"22\" rx=\"2\" fill=\"rgba(34,197,94,0.30)\"/>\n  <rect x=\"140\" y=\"105\" width=\"290\" height=\"12\" rx=\"1\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" opacity=\"0.85\"/>\n  <line x1=\"440\" y1=\"94\" x2=\"440\" y2=\"126\" stroke=\"var(--origam-color__feedback--danger---bg, #ef4444)\" stroke-width=\"3\" stroke-linecap=\"round\"/>\n  <text x=\"32\" y=\"115\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" font-family=\"''JetBrains Mono'',monospace\" text-anchor=\"end\">Profit</text>\n  <line x1=\"140\" y1=\"148\" x2=\"620\" y2=\"148\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1\"/>\n  <text x=\"140\" y=\"160\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">0</text>\n  <text x=\"260\" y=\"160\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">100</text>\n  <text x=\"380\" y=\"160\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">200</text>\n  <text x=\"500\" y=\"160\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">300</text>\n  <circle cx=\"28\" cy=\"28\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"32\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"148\" cy=\"70\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"148\" y=\"74\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"260\" cy=\"70\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"260\" y=\"74\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"400\" cy=\"62\" r=\"9\" fill=\"var(--origam-color__feedback--danger---bg, rgba(239,68,68,0.85))\"/>\n  <text x=\"400\" y=\"66\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"140\" cy=\"148\" r=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"140\" y=\"152\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"36\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n  <text x=\"350\" y=\"245\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">② range bands stack left→right; ③ bar overlaid; ④ target tick; ⑤ axis</text>\n", "code": "<div class=\"origam-chart-bullet\" role=\"figure\" aria-label=\"KPI Overview\">\n  <div class=\"origam-chart-bullet__header\">\n    <div class=\"origam-chart-bullet__title\">KPI Overview</div>\n  </div>\n\n  <div class=\"origam-chart-bullet__body\">\n    <svg class=\"origam-chart-bullet__svg origam-chart__svg\" role=\"img\">\n      <title>KPI Overview</title>\n      <desc>Bullet chart with 3 indicators.</desc>\n\n      <!-- one <g> per bullet row -->\n      <g class=\"origam-chart__bullet-row\">\n        <!-- qualitative bands -->\n        <rect class=\"origam-chart__bullet-range\" />\n        <!-- actual-value bar (keyboard activatable) -->\n        <rect class=\"origam-chart__bullet-bar\" tabindex=\"0\" role=\"button\" />\n        <!-- target tick -->\n        <line class=\"origam-chart__bullet-target\" />\n        <!-- category label -->\n        <text class=\"origam-chart__bullet-label\">Revenue</text>\n      </g>\n\n      <!-- axis (showAxis=true) -->\n      <g class=\"origam-chart__bullet-axis\">\n        <line class=\"origam-chart__bullet-axis-line\" />\n        <text class=\"origam-chart__bullet-axis-tick\" />\n      </g>\n    </svg>\n\n    <!-- tooltip (showTooltip=true) -->\n    <origam-chart-tooltip />\n  </div>\n\n  <!-- legend (showLegend=true) -->\n  <origam-chart-legend />\n</div>", "legend": [{"cls": ".origam-chart-bullet", "num": 1, "descriptionKey": "components.chart_bullet.anatomy.root", "descriptionFallback": "Root element. CSS grid with areas: header / body / legend. role=\"figure\" + aria-label from title."}, {"cls": ".origam-chart__bullet-range", "num": 2, "descriptionKey": "components.chart_bullet.anatomy.range", "descriptionFallback": "SVG <rect> for each qualitative range band. Fill driven by rangeColors palette or per-range color."}, {"cls": ".origam-chart__bullet-bar", "num": 3, "descriptionKey": "components.chart_bullet.anatomy.bar", "descriptionFallback": "SVG <rect> for the actual-value bar. tabindex=\"0\" and role=\"button\" — keyboard activatable."}, {"cls": ".origam-chart__bullet-target", "num": 4, "descriptionKey": "components.chart_bullet.anatomy.target", "descriptionFallback": "SVG <line> representing the target/goal tick. stroke-linecap: round."}, {"cls": ".origam-chart__bullet-axis-line", "num": 5, "descriptionKey": "components.chart_bullet.anatomy.axis", "descriptionFallback": "SVG axis baseline and tick labels. Visible when showAxis=true."}, {"cls": ".origam-chart-bullet__header", "num": 6, "descriptionKey": "components.chart_bullet.anatomy.header", "descriptionFallback": "Title + subtitle block. Grid area: header. Rendered only when title or subtitle is provided."}], "classes": [{"cls": "origam-chart-bullet", "descriptionKey": "components.chart_bullet.anatomy.root", "descriptionFallback": "Root element — CSS grid layout."}, {"cls": "origam-chart-bullet__header", "descriptionKey": "components.chart_bullet.anatomy.header", "descriptionFallback": "Title and subtitle block."}, {"cls": "origam-chart-bullet__title", "descriptionKey": "components.chart_bullet.anatomy.title", "descriptionFallback": "Primary chart title."}, {"cls": "origam-chart-bullet__subtitle", "descriptionKey": "components.chart_bullet.anatomy.subtitle", "descriptionFallback": "Secondary chart subtitle."}, {"cls": "origam-chart-bullet__body", "descriptionKey": "components.chart_bullet.anatomy.body", "descriptionFallback": "Body area containing the SVG."}, {"cls": "origam-chart-bullet__svg", "descriptionKey": "components.chart_bullet.anatomy.svg", "descriptionFallback": "SVG canvas."}, {"cls": "origam-chart__bullet-row", "descriptionKey": "components.chart_bullet.anatomy.row", "descriptionFallback": "<g> grouping one bullet row."}, {"cls": "origam-chart__bullet-range", "descriptionKey": "components.chart_bullet.anatomy.range", "descriptionFallback": "Qualitative range band rect."}, {"cls": "origam-chart__bullet-bar", "descriptionKey": "components.chart_bullet.anatomy.bar", "descriptionFallback": "Actual-value bar rect."}, {"cls": "origam-chart__bullet-bar--active", "descriptionKey": "components.chart_bullet.anatomy.bar_active", "descriptionFallback": "Active modifier applied on hover/focus."}, {"cls": "origam-chart__bullet-target", "descriptionKey": "components.chart_bullet.anatomy.target", "descriptionFallback": "Target marker tick line."}, {"cls": "origam-chart__bullet-label", "descriptionKey": "components.chart_bullet.anatomy.label", "descriptionFallback": "Category label text."}, {"cls": "origam-chart__bullet-axis", "descriptionKey": "components.chart_bullet.anatomy.axis_group", "descriptionFallback": "Axis group (baseline + ticks)."}, {"cls": "origam-chart__bullet-axis-line", "descriptionKey": "components.chart_bullet.anatomy.axis_line", "descriptionFallback": "Axis baseline line."}, {"cls": "origam-chart__bullet-axis-tick", "descriptionKey": "components.chart_bullet.anatomy.axis_tick", "descriptionFallback": "Axis tick label."}, {"cls": "origam-chart-bullet--horizontal", "descriptionKey": "components.chart_bullet.anatomy.mod_horizontal", "descriptionFallback": "Modifier for horizontal orientation (default)."}, {"cls": "origam-chart-bullet--vertical", "descriptionKey": "components.chart_bullet.anatomy.mod_vertical", "descriptionFallback": "Modifier for vertical orientation."}, {"cls": "origam-chart-bullet--no-animation", "descriptionKey": "components.chart_bullet.anatomy.mod_no_animation", "descriptionFallback": "Disables entry animation."}], "svg