INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3017aa6d-f70a-49b8-955a-efa9ade81440', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'component', 'list-subheader', 'ListSubheader', 'Data Display', NULL, 'mdi-format-list-group', 'components.catalog.list_subheader.description', 'Section heading rendered inside a List. Supports inset indent and sticky positioning.', NULL, NULL, 'origam-list-subheader', NULL, 'packages/ds/src/components/List/OrigamListSubheader.vue', 'origam', NULL, NULL, '/stories/?story=components-list-subheader--design', '/docs/components/List/OrigamListSubheader.html', 'list', '{"a11y": {"notes": [{"noteKey": "components.list_subheader.a11y.semantic_note", "noteFallback": "For screen-reader accessibility, consider using tag=\"h2\" through \"h6\" so the subheader is part of the heading outline. The default <div> tag is appropriate when the list is not a standalone section."}, {"noteKey": "components.list_subheader.a11y.sticky_note", "noteFallback": "The sticky variant uses position: sticky; top: 0 — the parent list must have overflow: auto or overflow: scroll for this to work correctly."}, {"noteKey": "components.list_subheader.a11y.contrast_note", "noteFallback": "The default secondary text color may have reduced contrast. Ensure at least 4.5:1 contrast ratio when customising the color prop."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__text---secondary)", "tokenPath": "--origam-list-subheader---color", "descriptionKey": "components.list_subheader.tokens.color", "descriptionFallback": "Default text color (secondary)."}, {"type": "dimension", "value": "var(--origam-font__size---md)", "tokenPath": "--origam-list__subheader---font-size", "descriptionKey": "components.list_subheader.tokens.font_size", "descriptionFallback": "Font size (0.875rem)."}, {"type": "dimension", "value": "40px", "tokenPath": "--origam-list-subheader---min-height", "descriptionKey": "components.list_subheader.tokens.min_height", "descriptionFallback": "Minimum row height."}, {"type": "dimension", "value": "32px", "tokenPath": "--origam-list-subheader---inset-indent-padding", "descriptionKey": "components.list_subheader.tokens.inset_indent_padding", "descriptionFallback": "Indent applied in --inset mode to align with prepend icon items."}, {"type": "duration", "value": "var(--origam-motion__duration---medium)", "tokenPath": "--origam-list-subheader---transition-duration", "descriptionKey": "components.list_subheader.tokens.transition_duration", "descriptionFallback": "Transition duration for min-height changes."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"140\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"50\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"var(--origam-color__action--primary---bg, #a855f7)\" stroke-width=\"1\" stroke-dasharray=\"6 3\" opacity=\"0.6\"/>\n  <rect x=\"32\" y=\"44\" width=\"400\" height=\"22\" rx=\"2\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\"/>\n  <text x=\"232\" y=\"59\" font-size=\"10\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__text (label)</text>\n  <circle cx=\"28\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"42\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"60\" cy=\"44\" r=\"8\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"60\" y=\"48\" font-size=\"8\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <line x1=\"38\" y1=\"36\" x2=\"90\" y2=\"20\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"94\" y=\"22\" font-size=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" font-weight=\"700\" font-family=\"''JetBrains Mono'',monospace\">origam-list-subheader</text>\n  <text x=\"350\" y=\"125\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">--inset adds 32px indent-padding · --sticky sets position: sticky top: 0</text>\n", "legend": [{"cls": ".origam-list-subheader", "num": 1, "descriptionKey": "components.list_subheader.anatomy.root", "descriptionFallback": "Root element. Flex container (align-items: center). Renders as <code>&lt;div&gt;</code> by default; use <code>tag=\"h2\"</code>–<code>\"h6\"</code> for semantic sectioning."}, {"cls": ".origam-list-subheader__text", "num": 2, "descriptionKey": "components.list_subheader.anatomy.text", "descriptionFallback": "Label text wrapper. <code>overflow: hidden; text-overflow: ellipsis; white-space: nowrap</code>. Rendered only when the title prop or default slot is provided."}], "svgDesc": "Schematic of the ListSubheader component with 2 numbered internal parts.", "svgTitle": "Anatomy of OrigamListSubheader", "rootClass": "origam-list-subheader", "figcaption": "Anatomy of <code>&lt;origam-list-subheader&gt;</code> — 2 internal parts. The root ① is a flex container; the inner text element ② truncates with ellipsis.", "svgViewBox": "0 0 700 140"}, "cssVars": [{"name": "--origam-list-subheader---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.list_subheader.css_vars.color", "descriptionFallback": "Text color of the subheader label. Defaults to the semantic secondary text color."}, {"name": "--origam-list-subheader---font-size", "defaultValue": "0.875rem", "descriptionKey": "components.list_subheader.css_vars.font_size", "descriptionFallback": "Font size of the subheader label."}, {"name": "--origam-list-subheader---font-weight", "defaultValue": "400", "descriptionKey": "components.list_subheader.css_vars.font_weight", "descriptionFallback": "Font weight of the subheader label."}, {"name": "--origam-list-subheader---min-height", "defaultValue": "40px", "descriptionKey": "components.list_subheader.css_vars.min_height", "descriptionFallback": "Minimum height of the subheader row. Transitions with density changes."}, {"name": "--origam-list-subheader---padding-inline-end", "defaultValue": "16px", "descriptionKey": "components.list_subheader.css_vars.padding_inline_end", "descriptionFallback": "Trailing padding to avoid text running to the edge."}, {"name": "--origam-list-subheader---line-height", "defaultValue": "1.375rem", "descriptionKey": "components.list_subheader.css_vars.line_height", "descriptionFallback": "Line height of the subheader text."}, {"name": "--origam-list-subheader---inset-indent-padding", "defaultValue": "32px", "descriptionKey": "components.list_subheader.css_vars.inset_indent_padding", "descriptionFallback": "Indent padding applied when --inset modifier is active. Aligns the label with prepend icons."}, {"name": "--origam-list-subheader---transition-duration", "defaultValue": "0.2s", "descriptionKey": "components.list_subheader.css_vars.transition_duration", "descriptionFallback": "Duration of the min-height transition."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.list_subheader.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.list_subheader.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed listSubheaderStyles."}, {"name": "id", "type": "string", "descriptionKey": "components.list_subheader.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.list_subheader.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.list_subheader.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.list_subheader.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "text", "prop": "title", "labelKey": "components.list_subheader.playground.title", "defaultValue": "Section header", "labelFallback": "Title"}, {"kind": "switch", "prop": "inset", "labelKey": "components.list_subheader.playground.inset", "defaultValue": false, "labelFallback": "Inset"}, {"kind": "switch", "prop": "sticky", "labelKey": "components.list_subheader.playground.sticky", "defaultValue": false, "labelFallback": "Sticky"}]}, "previewVariants": [{"label": "default", "props": {"title": "Section header"}}, {"label": "inset", "props": {"inset": true, "title": "Inset header"}}, {"label": "sticky", "props": {"title": "Sticky header", "sticky": true}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
