lue": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.data_table.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "density", "options": [{"label": "(default)", "value": ""}, {"label": "default", "value": "default"}, {"label": "DENSITY.DEFAULT", "value": "DENSITY.DEFAULT"}, {"label": "compact", "value": "compact"}, {"label": "DENSITY.COMPACT", "value": "DENSITY.COMPACT"}, {"label": "DENSITY.COMFORTABLE", "value": "DENSITY.COMFORTABLE"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.data_table.playground.density", "defaultValue": "", "labelFallback": "Density"}, {"kind": "switch", "prop": "hideDefaultBody", "labelKey": "components.data_table.playground.hide_default_body", "defaultValue": false, "labelFallback": "Hide Default Body"}, {"kind": "switch", "prop": "hideDefaultFooter", "labelKey": "components.data_table.playground.hide_default_footer", "defaultValue": false, "labelFallback": "Hide Default Footer"}, {"kind": "switch", "prop": "hideDefaultHeader", "labelKey": "components.data_table.playground.hide_default_header", "defaultValue": false, "labelFallback": "Hide Default Header"}, {"kind": "switch", "prop": "returnObject", "labelKey": "components.data_table.playground.return_object", "defaultValue": false, "labelFallback": "Return Object"}, {"kind": "switch", "prop": "multiSort", "labelKey": "components.data_table.playground.multi_sort", "defaultValue": false, "labelFallback": "Multi Sort"}, {"kind": "switch", "prop": "mustSort", "labelKey": "components.data_table.playground.must_sort", "defaultValue": false, "labelFallback": "Must Sort"}], "defaultSlotContent": "Tab"}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('948504d2-6fa5-4db0-b7c3-6a37d78c196b', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'component', 'date-picker-months', 'DatePickerMonths', 'Form & Input', NULL, 'mdi-calendar-month-outline', 'components.catalog.date_picker_months.description', 'Month-grid view for picking a month within a given year. Renders 12 month buttons in a 2-column grid with min/max constraint support.', NULL, NULL, 'origam-date-picker-months', NULL, 'packages/ds/src/components/DatePicker/OrigamDatePickerMonths.vue', 'origam', NULL, NULL, '/stories/?story=components-datepicker--design', '/docs/components/DatePicker/OrigamDatePickerMonths.html', 'date-picker', '{"a11y": {"notes": [{"noteKey": "components.date_picker_months.a11y.disabled_note", "noteFallback": "Months outside the min/max range receive disabled=true on the inner OrigamBtn and are skipped in keyboard navigation."}], "roles": ["button"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.date_picker_months.a11y.key_select", "actionFallback": "Selects the focused month."}, {"key": "Tab", "actionKey": "components.date_picker_months.a11y.key_tab", "actionFallback": "Moves focus between month tiles."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__action--primary---bg)", "tokenPath": "--origam-date-picker__day---background-color-selected", "descriptionKey": "components.date_picker_months.tokens.selected_bg", "descriptionFallback": "Active month button background (driven by the color prop)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"220\" fill=\"var(--origam-color__surface---sunken, #f9fafb)\" rx=\"4\"/>\n  <!-- root -->\n  <rect x=\"140\" y=\"20\" width=\"420\" height=\"180\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <!-- 2-col grid: 6 rows of 2 -->\n  <rect x=\"160\" y=\"36\" width=\"174\" height=\"28\" rx=\"14\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"247\" y=\"54\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"system-ui\">Jan</text>\n  <rect x=\"362\" y=\"36\" width=\"174\" height=\"28\" rx=\"14\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"449\" y=\"54\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"system-ui\">Feb</text>\n  <rect x=\"160\" y=\"74\" width=\"174\" height=\"28\" rx=\"14\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"247\" y=\"92\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"system-ui\">Mar</text>\n  <rect x=\"362\" y=\"74\" width=\"174\" height=\"28\" rx=\"14\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"449\" y=\"92\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"system-ui\">Apr</text>\n  <!-- active month -->\n  <rect x=\"160\" y=\"112\" width=\"174\" height=\"28\" rx=\"14\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"247\" y=\"130\" font-size=\"10\" fill=\"#fff\" text-anchor=\"middle\" font-family=\"system-ui\" font-weight=\"600\">May</text>\n  <rect x=\"362\" y=\"112\" width=\"174\" height=\"28\" rx=\"14\" fill=\"none\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"449\" y=\"130\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" text-anchor=\"middle\" font-family=\"system-ui\">Jun</text>\n  <text x=\"350\" y=\"168\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">… (Jul – Dec)</text>\n  <!-- markers -->\n  <circle cx=\"148\" cy=\"28\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"148\" y=\"32.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"168\" cy=\"44\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"168\" y=\"48.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"168\" cy=\"120\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"168\" y=\"124.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div class=\"origam-date-picker-months\">\n  <div class=\"origam-date-picker-months__content\">\n    <!-- slot: #month — repeated for each of the 12 months -->\n    <origam-btn\n      v-for=\"(month, i) in months\"\n      :key=\"i\"\n      :active=\"model === i\"\n      :color=\"model === i ? color : undefined\"\n      :disabled=\"month.isDisabled\"\n      :rounded=\"true\"\n      :text=\"month.text\"\n      @click=\"handleClick(i)\"\n    />\n  </div>\n</div>", "legend": [{"cls": ".origam-date-picker-months", "num": 1, "descriptionKey": "components.date_picker_months.anatomy.root", "descriptionFallback": "Root container. Fixed height (288px by default). Overflow hidden."}, {"cls": ".origam-date-picker-months__content", "num": 2, "descriptionKey": "components.date_picker_months.anatomy.content", "descriptionFallback": "2-column CSS grid with justify-content: space-around. padding-inline: 36px. grid-gap: 0 24px. Inner OrigamBtn elements have text-transform: none."}, {"cls": "OrigamBtn (active)", "num": 3, "descriptionKey": "components.date_picker_months.anatomy.active_btn", "descriptionFallback": "The currently selected month button. Receives active=true and color=props.color. All buttons have rounded=true."}], "classes": [{"cls": "origam-date-picker-months", "descriptionKey": "components.date_picker_months.anatomy.root", "descriptionFallback": "Root container. Default height 288px."}, {"cls": "origam-date-picker-months__content", "descriptionKey": "components.date_picker_months.anatomy.content", "descriptionFallback": "2-column grid of month buttons."}], "svgDesc": "Schematic of the DatePickerMonths component showing a 2-column grid of 12 month buttons.", "svgTitle": "Anatomy of OrigamDatePickerMonths", "rootClass": "origam-date-picker-months", "figcaption": "Anatomy of <code>&lt;origam-date-picker-months&gt;</code> — 3 parts: ① root container (288px default height), ② the 2-column grid content wrapper, ③ the active month button highlighted with the <code>color</code> prop.", "svgViewBox": "0 0 700 220"}, "cssVars": [{"name": "--origam-date-picker-months---height", "defaultValue": "288px", "descriptionKey": "components.date_picker_months.css_vars.height", "descriptionFallback": "Container height. Overridden via the height prop (IDimensionProps)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.date_picker_months.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.date_picker_months.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.date_picker_months.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.date_picker_months.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.date_picker_months.exposed.unload", "descriptionFallback": "Removes the injected style sheet from the document."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.date_picker_months.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.date_picker_months.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}]}}', false, NULL, NULL, NULL, NULL, NULL, NULL);
