x)", "descriptionKey": "components.file_field_drag_n_drop_item.css_vars.progress_margin_top", "descriptionFallback": "Top margin of the progress bar inside the content column."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.file_field_drag_n_drop_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.file_field_drag_n_drop_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed root styles."}, {"name": "id", "type": "string", "descriptionKey": "components.file_field_drag_n_drop_item.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.file_field_drag_n_drop_item.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.file_field_drag_n_drop_item.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.file_field_drag_n_drop_item.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.file_field_drag_n_drop_item.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.file_field_drag_n_drop_item.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.file_field_drag_n_drop_item.playground.readonly", "defaultValue": false, "labelFallback": "Read-only"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('bfd6527b-8645-4d17-8b74-bdb4fb0f5679', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'component', 'file-field-list-item', 'FileFieldListItem', 'Form & Input', NULL, 'mdi-file-document-outline', 'components.catalog.file_field_list_item.description', 'File card rendered in list mode for each selected file. Displays name, human-readable size, an optional progress bar and a remove button. Renders as a semantic <li> element.', NULL, NULL, 'origam-file-field-list-item', NULL, 'packages/ds/src/components/FileField/OrigamFileFieldListItem.vue', 'origam', NULL, NULL, '/stories/?story=components-filefield--design', '/docs/components/FileField/OrigamFileField.html', 'file-field', '{"a11y": {"notes": [{"noteKey": "components.file_field_list_item.a11y.semantic_li", "noteFallback": "The root element is a semantic <li>. It must be used inside a <ul> (provided by OrigamFileField in list display mode) to satisfy the HTML content model."}, {"noteKey": "components.file_field_list_item.a11y.remove_btn", "noteFallback": "The remove button is a native <button> (via OrigamBtn). It is disabled when disabled=true or readonly=true."}], "roles": ["listitem"], "keyboard": [{"key": "Enter / Space", "actionKey": "components.file_field_list_item.a11y.key_remove", "actionFallback": "Activates the remove button when focused — native <button> behaviour."}, {"key": "Tab", "actionKey": "components.file_field_list_item.a11y.key_tab", "actionFallback": "Moves focus to the remove button and then to the next interactive element."}]}, "tokens": {"excerpt": [{"type": "color", "value": "var(--origam-color__surface---overlay)", "tokenPath": "--origam-file-field-list-item---background-color", "descriptionKey": "components.file_field_list_item.tokens.background_color", "descriptionFallback": "Card background color."}, {"type": "color", "value": "var(--origam-color__border---subtle)", "tokenPath": "--origam-file-field-list-item---border-color", "descriptionKey": "components.file_field_list_item.tokens.border_color", "descriptionFallback": "Card border color."}, {"type": "dimension", "value": "var(--origam-radius---sm)", "tokenPath": "--origam-file-field-list-item---border-radius", "descriptionKey": "components.file_field_list_item.tokens.border_radius", "descriptionFallback": "Card corner radius."}, {"type": "dimension", "value": "var(--origam-space---3)", "tokenPath": "--origam-file-field-list-item---gap", "descriptionKey": "components.file_field_list_item.tokens.gap", "descriptionFallback": "Gap between icon, content and actions (12px)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"160\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"20\" y=\"30\" width=\"660\" height=\"100\" rx=\"6\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <circle cx=\"28\" cy=\"38\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"28\" y=\"42\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <rect x=\"40\" y=\"44\" width=\"60\" height=\"72\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f3eeff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"70\" y=\"83\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">icon</text>\n  <circle cx=\"48\" cy=\"52\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"48\" y=\"56\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <rect x=\"116\" y=\"44\" width=\"450\" height=\"72\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f9f5ff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\"/>\n  <text x=\"210\" y=\"64\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #3b1c6e)\" font-weight=\"600\" font-family=\"''JetBrains Mono'',monospace\">document.docx</text>\n  <text x=\"210\" y=\"80\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #7e5fb0)\" font-family=\"''JetBrains Mono'',monospace\">320 kB</text>\n  <rect x=\"136\" y=\"90\" width=\"410\" height=\"6\" rx=\"3\" fill=\"var(--origam-color__surface---overlay, rgba(124,58,237,0.12))\"/>\n  <rect x=\"136\" y=\"90\" width=\"267\" height=\"6\" rx=\"3\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <circle cx=\"124\" cy=\"52\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"124\" y=\"56\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"340\" cy=\"95\" r=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\"/>\n  <text x=\"340\" y=\"99\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <rect x=\"580\" y=\"44\" width=\"72\" height=\"72\" rx=\"4\" fill=\"var(--origam-color__surface---sunken, #f3eeff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"616\" y=\"83\" font-size=\"9\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">remove</text>\n  <circle cx=\"588\" cy=\"52\" r=\"8\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"588\" y=\"56\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<li class=\"origam-file-field-list-item\">\n  <slot>\n    <origam-icon class=\"origam-file-field-list-item__icon\" />\n    <div class=\"origam-file-field-list-item__content\">\n      <div class=\"origam-file-field-list-item__name\">document.docx</div>\n      <div class=\"origam-file-field-list-item__meta\">320 kB</div>\n      <origam-progress class=\"origam-file-field-list-item__progress\" />\n    </div>\n    <div class=\"origam-file-field-list-item__actions\">\n      <origam-btn :icon=\"removeIcon\" flat size=\"small\" @click.stop=\"handleRemove\" />\n    </div>\n  </slot>\n</li>", "legend": [{"cls": ".origam-file-field-list-item", "num": 1, "descriptionKey": "components.file_field_list_item.anatomy.root", "descriptionFallback": "Root <li> element. display: flex; align-items: center. Has background-color, border (1px solid), border-radius and padding from design tokens."}, {"cls": ".origam-file-field-list-item__icon", "num": 2, "descriptionKey": "components.file_field_list_item.anatomy.icon", "descriptionFallback": "OrigamIcon rendered from the fileIcon prop. flex-shrink: 0; color from --origam-file-field-list-item__icon---color."}, {"cls": ".origam-file-field-list-item__content", "num": 3, "descriptionKey": "components.file_field_list_item.anatomy.content", "descriptionFallback": "Flex column: stacks __name, __meta and optional __progress. flex-grow: 1; min-width: 0 for truncation support."}, {"cls": ".origam-file-field-list-item__progress", "num": 4, "descriptionKey": "components.file_field_list_item.anatomy.progress", "descriptionFallback": "OrigamProgress bar. Rendered only when the progress prop is a number. height: 4px; rounded; has margin-top from token."}, {"cls": ".origam-file-field-list-item__actions", "num": 5, "descriptionKey": "components.file_field_list_item.anatomy.actions", "descriptionFallback": "Flex row of action buttons. flex-shrink: 0. Contains the remove OrigamBtn (flat, size=\"small\")."}], "classes": [{"cls": "origam-file-field-list-item", "descriptionKey": "components.file_field_list_item.anatomy.root", "descriptionFallback": "Root <li> flex container with background, border, border-radius and padding tokens."}, {"cls": "origam-file-field-list-item__icon", "descriptionKey": "components.file_field_list_item.anatomy.icon", "descriptionFallback": "File type icon (flex-shrink: 0)."}, {"cls": "origam-file-field-list-item__content", "descriptionKey": "components.file_field_list_item.anatomy.content", "descriptionFallback": "Column container for name, meta and progress."}, {"cls": "origam-file-field-list-item__name", "descriptionKey": "components.file_field_list_item.anatomy.name", "descriptionFallback": "File name text. Truncated with text-overflow: ellipsis."}, {"cls": "origam-file-field-list-item__meta", "descriptionKey": "components.file_field_list_item.anatomy.meta", "descriptionFallback": "Human-readable file size text."}, {"cls": "origam-file-field-list-item__progress", "descriptionKey": "components.file_field_list_item.anatomy.progress", "descriptionFallback": "Upload progress bar (conditional on progress prop)."}, {"cls": "origam-file-field-list-item__actions", "descriptionKey": "components.file_field_list_item.anatomy.actions", "descriptionFallback": "Action buttons zone (remove button)."}], "svgDesc": "Schematic of the list file item with 5 numbered parts: root <li>, icon, content column, progress bar, actions.", "svgTitle": "Anatomy of OrigamFileFieldListItem", "rootClass": "origam-file-field-list-item", "figcaption": "Anatomy of <code>&lt;origam-file-field-list-item&gt;</code> — renders as a semantic <code>&lt;li&gt;</code>. 5 internal parts: root card ①, file icon ②, content column ③ (name + meta + optional progress ④), and the actions zone ⑤ with the remove button.", "svgViewBox": "0 0 700 160"}, "cssVars": [{"name": "--origam-file-field-list-item---background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.file_field_list_item.css_vars.background_color", "descriptionFallback": "Card background color."}, {"name": "--origam-file-field-list-item---border-color", "defaultValue": "{color.border.subtle}", "descriptionKey": "components.file_field_list_item.css_vars.border_color", "descriptionFallback": "Card border color."}, {"name": "--origam-file-field-list-item---border-width", "defaultValue": "1px", "descriptionKey": "components.file_field_list_item.css_vars.border_width", "descriptionFallback": "Card border width."}, {"name": "--origam-file-field-list-item---border-style", "defaultValue": "solid", "descriptionKey": "components.file_field_list_item.css_vars.border_style", "descriptionFallback": "Card border style."}, {"name": "--origam-file-field-list-item---border-radius", "defaultValue": "{radius.sm} (6px)", "descriptionKey": "components.file_field_list_item.css_vars.border_radius", "descriptionFallback": "Card corner radius (6px as fallback in the .vue; closest token is radius.sm = 4px)."}, {"name": "--origam-file-field-list-item---gap", "defaultValue": "{space.3} (12px)", "descriptionKey": "components.file_field_list_item.css_vars.gap", "descriptionFallback": "Gap between the icon, content column and actions zone."}, {"name": "--origam-file-field-list-item---padding-block", "defaultValue": "{space.2} (10px)", "descriptionKey": "components.file_field_list_item.css_vars.padding_block", "descriptionFallback": "Block (top/bottom) padding of the card."}, {"name": "--origam-file-field-list-item---padding-inline", "defaultValue": "{space.3} (12px)", "descriptionKey": "components.file_field_list_item.css_vars.padding_inline", "descriptionFallback": "Inline (left/right) padding of the card."}, {"name": "--origam-file-field-list-item__icon---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.file_field_list_item.css_vars.icon_color", "descriptionFallback": "Color of the file type icon glyph."}, {"name": "--origam-file-field-list-item__name---font-size", "defaultValue": "{font.size.md} (0.875rem)", "descriptionKey": "components.file_field_list_item.css_vars.name_font_size", "descriptionFallback": "Font size for the file name label."}, {"name": "--origam-file-field-list-item__name---font-weight", "defaultValue": "{font.weight.medium} (500)", "descriptionKey": "components.file_field_list_item.css_vars.name_font_weight", "descriptionFallback": "Font weight for the file name label."}, {"name": "--origam-file-field-list-item__meta---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.file_field_list_item.css_vars.meta_color", "descriptionFallback": "Color of the file size / meta text."}, {"name": "--origam-file-field-list-item__meta---font-size", "defaultValue": "{font.size.sm} (0.75rem)", "descriptionKey": "components.file_field_list_item.css_vars.meta_font_size", "descriptionFallback": "Font size for the file size / meta text."}, {"name": "--origam-file-field-list-item__progress---margin-top", "defaultValue": "{space.1} (4px)", "descriptionKey": "components.file_field_list_item.css_vars.progress_margin_top", "descriptionFallback": "Top margin of the progress bar inside the content column."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.file_field_list_item.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to child components."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.file_field_list_item.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle from the computed root styles."}, {"name": "id", "type": "string", "descriptionKey": "components.file_field_list_item.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.file_field_list_item.exposed.load", "descriptionFallback": "Injects the computed style sheet into the document."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.file_field_list_item.exposed.unload", "descriptionFallback": "Removes the injected style sheet."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.file_field_list_item.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.file_field_list_item.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.file_field_list_item.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.file_field_list_item.playground.readonly", "defaultValue": false, "labelFallback": "Read-only"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('5a02b506-ceb1-4df0-b336-beaa6f0d84bd', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'component', 'form', 'Form', 'Form & Input', NULL, 'mdi-form-select', 'components.catalog.form.description', 'Form container with centralised validation, global error messaging, accessible submit/reset lifecycle, and an optional scroll-to-first-error behaviour. Wraps any number of Origam input fields and coordinates their validation state.', NULL, NULL, 'origam-form', NULL, 'packages/ds/src/components/Form/OrigamForm.vue', 'origam', NULL, NULL, '/stories/?story=components-form--design', '/docs/components/Form/OrigamForm.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.form.a11y.novalidate", "noteFallback": "The form element uses novalidate to suppress browser-native validation bubbles. All validation is handled by Origam components and displayed in field detail zones."}, {"noteKey": "components.form.a11y.live_region", "noteFallback": "Form-level messages appear in the __details section via OrigamMessages which carries aria-live=\"polite\" internally. Screen readers announce errors after submit."}, {"noteKey": "components.form.a11y.scroll_to_error", "noteFallback": "scrollToError (prop) and scrollToFirstError (exposed method) move focus to the first errored field after validation. This is an important accessibility improvement for long forms — screen readers naturally encounter the error context without manual navigation."}, {"noteKey": "components.form.a11y.disabled", "noteFallback": "Setting disabled=true injects IFormProvide.isDisabled = true into all descendant fields via provide/inject. No need to set disabled individually on each field."}], "roles": [], "keyboard": [{"key": "Enter (on submit button)", "actionKey": "components.form.a11y.key_submit", "actionFallback": "Submits the form when focus is on a [type=submit] button inside the form."}, {"key": "Escape", "actionKey": "components.form.a11y.key_escape", "actionFallback": "No built-in behaviour — consumers may bind Escape to call reset() or navigate away."}]}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-form__actions---margin-top", "descriptionKey": "components.form.tokens.actions_margin_top", "descriptionFallback": "Top margin of the actions zone (16px)."}, {"type": "dimension", "value": "var(--origam-space---2)", "tokenPath": "--origam-form__actions---gap", "descriptionKey": "components.form.tokens.actions_gap", "descriptionFallback": "Gap between action buttons (8px)."}, {"type": "dimension", "value": "var(--origam-font__size---sm)", "tokenPath": "--origam-form__details---font-size", "descriptionKey": "components.form.tokens.details_font_size", "descriptionFallback": "Message text font size (0.75rem)."}, {"type": "dimension", "value": "22px", "tokenPath": "--origam-form__details---min-height", "descriptionKey": "components.form.tokens.details_min_height", "descriptionFallback": "Minimum height of the message zone."}, {"type": "color", "value": "var(--origam-color__feedback--danger---fgSubtle)", "tokenPath": "--origam-form--error---messages-color", "descriptionKey": "components.form.tokens.error_messages_color", "descriptionFallback": "Error message colour."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"16\" width=\"644\" height=\"168\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"48\" y=\"32\" width=\"604\" height=\"80\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"76\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__content (#default slot — form fields)</text>\n  <rect x=\"48\" y=\"124\" width=\"604\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__feedback--danger---bgSubtle, rgba(220,38,38,0.05))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"350\" y=\"140\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">__details (OrigamMessages — error / hint)</text>\n  <rect x=\"48\" y=\"156\" width=\"200\" height=\"20\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"148\" y=\"169\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">__actions (#actions slot)</text>\n  <circle cx=\"36\" cy=\"24\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"28.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"40\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"44\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"56\" cy=\"132\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"136\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<form class=\"origam-form\" novalidate @submit=\"handleSubmit\" @reset=\"handleReset\">\n\n  <!-- input fields register automatically via inject(IFormProvide) -->\n  <div class=\"origam-form__content\">\n    <slot name=\"default\" v-bind=\"form\" />\n  </div>\n\n  <!-- form-level error / hint messages — v-if hasMessages -->\n  <div class=\"origam-form__details\">\n    <slot name=\"messages\" v-bind=\"{ hasMessages, messages }\">\n      <origam-messages :messages=\"messages\" />\n    </slot>\n  </div>\n\n  <!-- action buttons — v-if slots.actions -->\n  <div class=\"origam-form__actions\">\n    <slot name=\"actions\" v-bind=\"{ submit, reset }\" />\n  </div>\n</form>", "legend": [{"cls": ".origam-form", "num": 1, "descriptionKey": "components.form.anatomy.root", "descriptionFallback": "Root <form> element with novalidate (prevents browser default validation). Handles @submit and @reset natively."}, {"cls": ".origam-form__content", "num": 2, "descriptionKey": "components.form.anatomy.content", "descriptionFallback": "Wrapper div hosting the #default slot. Contains all field components that register with the form."}, {"cls": ".origam-form__details", "num": 3, "descriptionKey": "components.form.anatomy.details", "descriptionFallback": "Form-level messages zone. Renders OrigamMessages when there are form-level errors or hints. Hidden when no messages are active."}, {"cls": ".origam-form__actions", "num": 4, "descriptionKey": "components.form.anatomy.actions", "descriptionFallback": "Actions row. Rendered only when the #actions slot is provided. Flex container with gap and top margin."}], "classes": [{"cls": "origam-form", "descriptionKey": "components.form.anatomy.root", "descriptionFallback": "Root <form> element."}, {"cls": "origam-form--error", "descriptionKey": "components.form.anatomy.error", "descriptionFallback": "Applied when form-level validation fails. Changes message/icon colour to danger semantic."}, {"cls": "origam-form__content", "descriptionKey": "components.form.anatomy.content", "descriptionFallback": "Form fields wrapper."}, {"cls": "origam-form__details", "descriptionKey": "components.form.anatomy.details", "descriptionFallback": "Form-level message zone (error / hint)."}, {"cls": "origam-form__actions", "descriptionKey": "components.form.anatomy.actions", "descriptionFallback": "Action buttons row. Flex with gap."}], "svgDesc": "Schematic of the Form component with 3 numbered internal parts.", "svgTitle": "Anatomy of OrigamForm", "rootClass": "origam-form", "figcaption": "Anatomy of <code>&lt;origam-form&gt;</code> — 3 internal zones. The root ① is a native <code>&lt;form novalidate&gt;</code>. Content ② holds the input fields. Details ③ shows form-level error/hint messages via OrigamMessages.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-form__actions---margin-top", "defaultValue": "{space.4} (16px)", "descriptionKey": "components.form.css_vars.actions_margin_top", "descriptionFallback": "Top margin separating the actions row from the form body."}, {"name": "--origam-form__actions---gap", "defaultValue": "{space.2} (8px)", "descriptionKey": "components.form.css_vars.actions_gap", "descriptionFallback": "Gap between action buttons in the __actions row."}, {"name": "--origam-form__details---font-size", "defaultValue": "{font.size.sm} (0.75rem)", "descriptionKey": "components.form.css_vars.details_font_size", "descriptionFallback": "Font size of form-level messages."}, {"name": "--origam-form__details---min-height", "defaultValue": "22px", "descriptionKey": "components.form.css_vars.details_min_height", "descriptionFallback": "Minimum height of the details zone. Prevents layout shift when messages appear."}, {"name": "--origam-form--error---messages-color", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.form.css_vars.error_messages_color", "descriptionFallback": "Message text colour in error state."}, {"name": "--origam-form--error---icon-color", "defaultValue": "{color.feedback.danger.fgSubtle}", "descriptionKey": "components.form.css_vars.error_icon_color", "descriptionFallback": "Icon colour in error state."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.form.exposed.filter_props", "descriptionFallback": "Filters and forwards props to child components."}, {"name": "submit", "type": "() => void", "descriptionKey": "components.form.exposed.submit", "descriptionFallback": "Triggers form validation and submit. Equivalent to clicking a [type=submit] button."}, {"name": "reset", "type": "() => void", "descriptionKey": "components.form.exposed.reset", "descriptionFallback": "Resets all child fields to their initial value and clears validation errors."}, {"name": "validate", "type": "() => Promise<IFormValidationResult>", "descriptionKey": "components.form.exposed.validate", "descriptionFallback": "Programmatically validates all registered child fields. Returns { valid, errors }."}, {"name": "resetValidation", "type": "() => void", "descriptionKey": "components.form.exposed.reset_validation", "descriptionFallback": "Clears all validation errors without resetting field values."}, {"name": "isValid", "type": "Ref<boolean | null>", "descriptionKey": "components.form.exposed.is_valid", "descriptionFallback": "Current overall validity: true (valid), false (invalid), null (pending)."}, {"name": "isValidating", "type": "Ref<boolean>", "descriptionKey": "components.form.exposed.is_validating", "descriptionFallback": "True while async validators are running."}, {"name": "items", "type": "Ref<IFormField[]>", "descriptionKey": "components.form.exposed.items", "descriptionFallback": "All registered child field descriptors (id, validate, reset, resetValidation, isValid, errorMessages)."}, {"name": "errors", "type": "ComputedRef<IFieldValidationResult[]>", "descriptionKey": "components.form.exposed.errors", "descriptionFallback": "Flat list of { id, errorMessages } for all fields currently in error."}, {"name": "scrollToFirstError", "type": "(options?: boolean | ScrollIntoViewOptions) => Promise<void>", "descriptionKey": "components.form.exposed.scroll_to_first_error", "descriptionFallback": "Scrolls to the first .origam-input--error element in the form DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "disabled", "labelKey": "components.form.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "switch", "prop": "readonly", "labelKey": "components.form.playground.readonly", "defaultValue": false, "labelFallback": "Readonly"}, {"kind": "switch", "prop": "fastFail", "labelKey": "components.form.playground.fast_fail", "defaultValue": false, "labelFallback": "Fast fail"}, {"kind": "select", "prop": "validateOn", "options": [{"label": "(default)", "value": ""}, {"label": "blur", "value": "blur"}, {"label": "input", "value": "input"}, {"label": "submit", "value": "submit"}], "labelKey": "components.form.playground.validate_on", "defaultValue": "", "labelFallback": "Validate on"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ae70b0f1-6351-41c9-8408-e734eb1c99ed', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'component', 'grid', 'Grid', 'Layout & Structure', NULL, 'mdi-grid', 'components.catalog.grid.description', 'Declarative CSS Grid container. Exposes every CSS grid property through typed Vue props — no JS track measurement, no fallback to flexbox. columns, rows, gap, areas, autoFlow and alignment props map directly to the corresponding CSS grid properties.', NULL, NULL, 'origam-grid', NULL, 'packages/ds/src/components/Grid/OrigamGrid.vue', 'origam', NULL, NULL, '/stories/?story=components-grid--design', '/docs/components/Grid/OrigamGrid.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.grid.a11y.semantic_root", "noteFallback": "The tag prop defaults to \"div\" — change it to a semantic element when the grid represents a meaningful structure (e.g. tag=\"ul\" with list items, tag=\"section\" for a named region)."}, {"noteKey": "components.grid.a11y.no_reorder", "noteFallback": "CSS Grid visual reordering (via order or explicit grid-row/column placement) can diverge from DOM order. Keyboard navigation follows DOM order — avoid visual arrangements that confuse users navigating by Tab."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "dimension", "value": "var(--origam-space---1)", "tokenPath": "--origam-grid---gap-xs", "descriptionKey": "components.grid.tokens.gap_xs", "descriptionFallback": "Gap size xs (4px)."}, {"type": "dimension", "value": "var(--origam-space---2)", "tokenPath": "--origam-grid---gap-sm", "descriptionKey": "components.grid.tokens.gap_sm", "descriptionFallback": "Gap size sm (8px)."}, {"type": "dimension", "value": "var(--origam-space---4)", "tokenPath": "--origam-grid---gap-md", "descriptionKey": "components.grid.tokens.gap_md", "descriptionFallback": "Gap size md / default (16px)."}, {"type": "dimension", "value": "var(--origam-space---6)", "tokenPath": "--origam-grid---gap-lg", "descriptionKey": "components.grid.tokens.gap_lg", "descriptionFallback": "Gap size lg (24px)."}, {"type": "dimension", "value": "var(--origam-space---8)", "tokenPath": "--origam-grid---gap-xl", "descriptionKey": "components.grid.tokens.gap_xl", "descriptionFallback": "Gap size xl (32px)."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"28\" y=\"24\" width=\"644\" height=\"132\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <rect x=\"48\" y=\"44\" width=\"184\" height=\"92\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"140\" y=\"94\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">item 1</text>\n  <rect x=\"244\" y=\"44\" width=\"184\" height=\"92\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"336\" y=\"94\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">item 2</text>\n  <rect x=\"440\" y=\"44\" width=\"212\" height=\"92\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.2))\" stroke-width=\"1\" stroke-dasharray=\"3 2\"/>\n  <text x=\"546\" y=\"94\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\">item 3</text>\n  <circle cx=\"36\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"36\" y=\"36.5\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"56\" cy=\"52\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"56\" y=\"56\" font-size=\"9\" fill=\"var(--origam-color__action--primary---fg, #fff)\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<!-- OrigamGrid — single declarative element -->\n<div\n  class=\"origam-grid\"\n  style=\"\n    --origam-grid---template-columns: repeat(3, 1fr);\n    --origam-grid---template-rows: auto;\n    --origam-grid---gap: var(--origam-grid---gap-md, 1rem);\n    --origam-grid---auto-flow: row;\n  \"\n>\n  <slot />\n</div>", "legend": [{"cls": ".origam-grid", "num": 1, "descriptionKey": "components.grid.anatomy.root", "descriptionFallback": "Root element. display: grid (or inline-grid when inline=true). All grid properties are applied as inline CSS custom properties computed from props."}, {"cls": "(slotted children)", "num": 2, "descriptionKey": "components.grid.anatomy.items", "descriptionFallback": "Grid items — any element placed in the default slot. No BEM wrapping. Use grid-area or span CSS on individual items for advanced placement."}], "classes": [{"cls": "origam-grid", "descriptionKey": "components.grid.anatomy.root", "descriptionFallback": "Root element. display: grid (or inline-grid). No BEM children."}], "svgDesc": "Schematic of the Grid component with 2 numbered internal parts.", "svgTitle": "Anatomy of OrigamGrid", "rootClass": "origam-grid", "figcaption": "Anatomy of <code>&lt;origam-grid&gt;</code>. The root ① is a single element with CSS Grid properties applied via inline custom properties. Items ② are slotted children — any DOM element, without a BEM wrapper.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-grid---gap-xs", "defaultValue": "{space.1} (4px)", "descriptionKey": "components.grid.css_vars.gap_xs", "descriptionFallback": "Gap token for size xs."}, {"name": "--origam-grid---gap-sm", "defaultValue": "{space.2} (8px)", "descriptionKey": "components.grid.css_vars.gap_sm", "descriptionFallback": "Gap token for size sm."}, {"name": "--origam-grid---gap-md", "defaultValue": "{space.4} (16px)", "descriptionKey": "components.grid.css_vars.gap_md", "descriptionFallback": "Gap token for size md (default)."}, {"name": "--origam-grid---gap-lg", "defaultValue": "{space.6} (24px)", "descriptionKey": "components.grid.css_vars.gap_lg", "descriptionFallback": "Gap token for size lg."}, {"name": "--origam-grid---gap-xl", "defaultValue": "{space.8} (32px)", "descriptionKey": "components.grid.css_vars.gap_xl", "descriptionFallback": "Gap token for size xl."}, {"name": "--origam-grid---template-columns", "defaultValue": "none", "descriptionKey": "components.grid.css_vars.template_columns", "descriptionFallback": "Computed grid-template-columns value set from the columns prop."}, {"name": "--origam-grid---template-rows", "defaultValue": "none", "descriptionKey": "components.grid.css_vars.template_rows", "descriptionFallback": "Computed grid-template-rows value set from the rows prop."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.grid.exposed.filter_props", "descriptionFallback": "Filters and forwards a subset of props."}, {"name": "columnsCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid.exposed.columns_css", "descriptionFallback": "Serialised grid-template-columns CSS value computed from the columns prop."}, {"name": "rowsCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid.exposed.rows_css", "descriptionFallback": "Serialised grid-template-rows CSS value computed from the rows prop."}, {"name": "areasCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid.exposed.areas_css", "descriptionFallback": "Serialised grid-template-areas CSS value computed from the areas prop."}, {"name": "gapCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid.exposed.gap_css", "descriptionFallback": "Resolved gap value (size token → CSS var reference, or raw CSS value)."}, {"name": "columnGapCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid.exposed.column_gap_css", "descriptionFallback": "Resolved column-gap value."}, {"name": "rowGapCss", "type": "ComputedRef<string | undefined>", "descriptionKey": "components.grid.exposed.row_gap_css", "descriptionFallback": "Resolved row-gap value."}], "playground": {"controls": [{"kind": "select", "prop": "columns", "options": [{"label": "1", "value": 1}, {"label": "2", "value": 2}, {"label": "3", "value": 3}, {"label": "4", "value": 4}, {"label": "6", "value": 6}, {"label": "12", "value": 12}, {"label": "auto-fill 200px", "value": "repeat(auto-fill, minmax(200px, 1fr))"}], "labelKey": "components.grid.playground.columns", "defaultValue": 3, "labelFallback": "Columns"}, {"kind": "select", "prop": "gap", "options": [{"label": "xs", "value": "xs"}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}], "labelKey": "components.grid.playground.gap", "defaultValue": "md", "labelFallback": "Gap"}, {"kind": "select", "prop": "alignItems", "options": [{"label": "stretch", "value": "stretch"}, {"label": "start", "value": "start"}, {"label": "end", "value": "end"}, {"label": "center", "value": "center"}], "labelKey": "components.grid.playground.align_items", "defaultValue": "stretch", "labelFallback": "Align items"}, {"kind": "switch", "prop": "inline", "labelKey": "components.grid.playground.inline", "defaultValue": false, "labelFallback": "Inline grid"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
