der---default, rgba(168,85,247,0.25))\" stroke-width=\"1\" stroke-dasharray=\"4 2\"/>\n  <text x=\"430\" y=\"128\" font-size=\"11\" fill=\"var(--origam-color__text---secondary, #5b3e8c)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-layout__wrapper</text>\n  <text x=\"430\" y=\"145\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">→ origam-main + slot content</text>\n  <circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"32\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"192\" cy=\"64\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"192\" y=\"68\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<div :id=\"layoutId\" ref=\"origamLayoutRef\" class=\"origam-layout\">\n  <div :id=\"`${layoutId}-wrapper`\" class=\"origam-layout__wrapper\">\n    <slot name=\"default\" />\n  </div>\n</div>", "legend": [{"cls": ".origam-layout", "num": 1, "descriptionKey": "components.layout.anatomy.root", "descriptionFallback": "Root <code>&lt;div&gt;</code>. Emits <code>--origam-layout---position-{top,right,bottom,left}</code> CSS vars reflecting each registered item''s reserved space."}, {"cls": ".origam-layout__wrapper", "num": 2, "descriptionKey": "components.layout.anatomy.wrapper", "descriptionFallback": "Inner wrapper — <code>width: 100%; height: 100%</code>. In <code>full-height</code> mode switches to <code>100vw / 100vh</code>."}], "classes": [{"cls": "origam-layout", "descriptionKey": "components.layout.anatomy.root", "descriptionFallback": "Root element. position: relative; width: 100%; height: 100%."}, {"cls": "origam-layout__wrapper", "descriptionKey": "components.layout.anatomy.wrapper", "descriptionFallback": "Inner wrapper. width: 100%; height: 100%; max-height: 100%; max-width: 100%."}, {"cls": "origam-layout--full-height", "descriptionKey": "components.layout.anatomy.full_height", "descriptionFallback": "Applied when fullHeight=true. Switches wrapper to 100vw / 100vh."}], "svgDesc": "Schematic of the Layout component with its wrapper child and registered layout items.", "svgTitle": "Anatomy of OrigamLayout", "rootClass": "origam-layout", "figcaption": "Anatomy of <code>&lt;origam-layout&gt;</code> — root wrapper (①) + inner <code>__wrapper</code> (②) that receives the content. Layout items (Drawer, AppBar…) register themselves and carve space via CSS vars.", "svgViewBox": "0 0 700 240"}, "cssVars": [{"name": "--origam-layout---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.layout.css_vars.background_color", "descriptionFallback": "Layout background color."}, {"name": "--origam-layout---position-top", "defaultValue": "0px", "descriptionKey": "components.layout.css_vars.position_top", "descriptionFallback": "Space reserved at the top by registered layout items (e.g. AppBar height). Consumed by OrigamMain as padding-block-start."}, {"name": "--origam-layout---position-bottom", "defaultValue": "0px", "descriptionKey": "components.layout.css_vars.position_bottom", "descriptionFallback": "Space reserved at the bottom (e.g. BottomNav height). Consumed by OrigamMain as padding-block-end."}, {"name": "--origam-layout---position-left", "defaultValue": "0px", "descriptionKey": "components.layout.css_vars.position_left", "descriptionFallback": "Space reserved on the left (e.g. Drawer width). Consumed by OrigamMain as padding-inline-start."}, {"name": "--origam-layout---position-right", "defaultValue": "0px", "descriptionKey": "components.layout.css_vars.position_right", "descriptionFallback": "Space reserved on the right (e.g. rail nav width). Consumed by OrigamMain as padding-inline-end."}], "exposed": [{"name": "getLayoutItem", "type": "(id: string) => ILayerItem | undefined", "descriptionKey": "components.layout.exposed.get_layout_item", "descriptionFallback": "Returns the layout metadata (position, size, id) of a registered item by its string ID."}, {"name": "items", "type": "Ref<Array<ILayerItem>>", "descriptionKey": "components.layout.exposed.items", "descriptionFallback": "Reactive array of all registered layout items with their current positions and sizes."}, {"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.layout.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child component."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.layout.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.layout.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.layout.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.layout.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.layout.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "fullHeight", "labelKey": "components.layout.playground.full_height", "defaultValue": false, "labelFallback": "Full height (100vw/100vh)"}, {"kind": "select", "prop": "bgColor", "options": [{"label": "(default)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "surface", "value": "surface"}], "labelKey": "components.layout.playground.bg_color", "defaultValue": "", "labelFallback": "Background color"}, {"kind": "select", "prop": "elevation", "options": [{"label": "(none)", "value": ""}, {"label": "1", "value": "1"}, {"label": "2", "value": "2"}, {"label": "4", "value": "4"}], "labelKey": "components.layout.playground.elevation", "defaultValue": "", "labelFallback": "Elevation"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d2dcb388-869d-47b4-98de-9ab639002c47', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'component', 'lazy', 'Lazy', 'Layout & Structure', NULL, 'mdi-image-filter-none', 'components.catalog.lazy.description', 'Defers the mounting of its children until the placeholder enters the viewport. Uses IntersectionObserver (v-intersect directive) with an optional fade-in transition.', NULL, NULL, 'origam-lazy', NULL, 'packages/ds/src/components/Lazy/OrigamLazy.vue', 'origam', NULL, NULL, '/stories/?story=components-lazy--design', '/docs/components/Lazy/OrigamLazy.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.lazy.a11y.aria_busy_note", "noteFallback": "While the content is not yet revealed, the root element carries <code>aria-busy=\"true\"</code>. This signals to assistive technologies that the region is still loading."}, {"noteKey": "components.lazy.a11y.intersection_note", "noteFallback": "OrigamLazy relies on IntersectionObserver. Ensure placeholder dimensions are set (min-height / height) so the browser can observe a non-zero element. A zero-size element may never intersect and the content would never mount."}, {"noteKey": "components.lazy.a11y.reduced_motion_note", "noteFallback": "The default OrigamFade transition respects prefers-reduced-motion: reduce — pass transition=\"null\" to fully disable animation."}], "roles": [], "keyboard": []}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"24\" y=\"24\" width=\"300\" height=\"152\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.35))\" stroke-width=\"1.5\" stroke-dasharray=\"6 3\"/>\n  <text x=\"174\" y=\"96\" font-size=\"11\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">placeholder</text>\n  <text x=\"174\" y=\"112\" font-size=\"9\" fill=\"var(--origam-color__text---disabled, #b5a0d8)\" text-anchor=\"middle\" font-style=\"italic\">(min-height applied, children not mounted)</text>\n  <rect x=\"376\" y=\"24\" width=\"300\" height=\"152\" rx=\"4\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.06))\" stroke=\"var(--origam-color__action--primary---bg, #7c3aed)\" stroke-width=\"1.5\"/>\n  <text x=\"526\" y=\"88\" font-size=\"11\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">revealed</text>\n  <text x=\"526\" y=\"104\" font-size=\"9\" fill=\"var(--origam-color__text---tertiary, #7e5fb0)\" text-anchor=\"middle\" font-style=\"italic\">(children mounted + fade transition)</text>\n  <circle cx=\"32\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__border---default, rgba(168,85,247,0.5))\"/>\n  <text x=\"32\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"384\" cy=\"32\" r=\"10\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"384\" y=\"36.5\" font-size=\"9\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n", "code": "<component :is=\"tag\" v-intersect=\"intersect\" :aria-busy=\"!isActive || undefined\" class=\"origam-lazy\">\n  <!-- children rendered only when isActive=true -->\n  <template v-if=\"isActive\">\n    <origam-transition :transition=\"transition\" appear>\n      <slot name=\"default\" />\n    </origam-transition>\n  </template>\n</component>", "legend": [{"cls": ".origam-lazy (placeholder)", "num": 1, "descriptionKey": "components.lazy.anatomy.placeholder", "descriptionFallback": "While <code>isActive=false</code>, the root element is an empty block with the configured dimensions. The <code>v-intersect</code> directive watches it."}, {"cls": ".origam-lazy (revealed)", "num": 2, "descriptionKey": "components.lazy.anatomy.revealed", "descriptionFallback": "Once <code>isActive=true</code>, the default slot is rendered inside an <code>&lt;origam-transition&gt;</code> (OrigamFade by default). The element is never hidden again."}], "classes": [{"cls": "origam-lazy", "descriptionKey": "components.lazy.anatomy.root", "descriptionFallback": "Root element. Carries dimension styles and the v-intersect watcher."}], "svgDesc": "Schematic of the Lazy component in its two states: placeholder and revealed.", "svgTitle": "Anatomy of OrigamLazy", "rootClass": "origam-lazy", "figcaption": "Anatomy of <code>&lt;origam-lazy&gt;</code> — ① placeholder state (children unmounted, min-height reserves space for IntersectionObserver) → ② revealed state (children mounted with transition).", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-lazy---transition-duration", "defaultValue": "{motion.duration.medium}", "descriptionKey": "components.lazy.css_vars.transition_duration", "descriptionFallback": "Duration of the reveal transition (OrigamFade)."}, {"name": "--origam-lazy---transition-timing-function", "defaultValue": "{motion.easing.standard}", "descriptionKey": "components.lazy.css_vars.transition_timing_function", "descriptionFallback": "Easing of the reveal transition."}, {"name": "--origam-lazy---placeholder-min-height", "defaultValue": "{space.10}", "descriptionKey": "components.lazy.css_vars.placeholder_min_height", "descriptionFallback": "Minimum height of the placeholder zone so the IntersectionObserver has something to detect."}, {"name": "--origam-lazy---placeholder-background-color", "defaultValue": "{color.surface.overlay}", "descriptionKey": "components.lazy.css_vars.placeholder_background_color", "descriptionFallback": "Background color of the placeholder zone (visible only before reveal)."}], "exposed": [{"name": "filterProps", "type": "<T extends object>(props: T, exclude?: string[]) => Partial<T>", "descriptionKey": "components.lazy.exposed.filter_props", "descriptionFallback": "Utility to forward a filtered subset of props to a child."}, {"name": "css", "type": "Ref<string>", "descriptionKey": "components.lazy.exposed.css", "descriptionFallback": "Reactive CSS string generated by useStyle."}, {"name": "id", "type": "string", "descriptionKey": "components.lazy.exposed.id", "descriptionFallback": "Unique style-sheet ID for this instance."}, {"name": "load", "type": "() => void", "descriptionKey": "components.lazy.exposed.load", "descriptionFallback": "Injects the computed style sheet. Called automatically on mount."}, {"name": "unload", "type": "() => void", "descriptionKey": "components.lazy.exposed.unload", "descriptionFallback": "Removes the injected style sheet. Called automatically on unmount."}, {"name": "isLoaded", "type": "Ref<boolean>", "descriptionKey": "components.lazy.exposed.is_loaded", "descriptionFallback": "True once the style sheet has been injected into the DOM."}], "playground": {"controls": [{"kind": "switch", "prop": "modelValue", "labelKey": "components.lazy.playground.model_value", "defaultValue": false, "labelFallback": "Revealed (modelValue)"}, {"kind": "text", "prop": "height", "labelKey": "components.lazy.playground.height", "defaultValue": "200", "labelFallback": "Height (placeholder)"}, {"kind": "select", "prop": "tag", "options": [{"label": "div", "value": "div"}, {"label": "section", "value": "section"}, {"label": "article", "value": "article"}], "labelKey": "components.lazy.playground.tag", "defaultValue": "div", "labelFallback": "Tag"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('b61a8f14-ccce-4531-ba89-2b7536c95655', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'component', 'ligature-icon', 'LigatureIcon', 'Data Display', NULL, 'mdi-format-color-text', 'components.catalog.ligature_icon.description', 'Renders a Material Design ligature icon by placing the icon name as text content inside an element styled with the Material Icons font.', NULL, NULL, 'origam-ligature-icon', NULL, 'packages/ds/src/components/Icon/OrigamLigatureIcon.vue', 'origam', NULL, NULL, '/stories/?story=components-icon--design', '/docs/components/Icon/OrigamIcon.html', 'icon', '{"a11y": {"notes": [{"noteKey": "components.ligature_icon.a11y.decorative_note", "noteFallback": "Decorative icons should carry aria-hidden=\"true\" on the parent wrapper to hide them from assistive technologies."}, {"noteKey": "components.ligature_icon.a11y.font_note", "noteFallback": "Requires the Material Icons or Material Symbols Outlined font to be loaded in the page. Without the font, the raw ligature text string is shown instead of the glyph."}], "roles": [], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "currentColor", "tokenPath": "--origam-icon---color", "descriptionKey": "components.ligature_icon.tokens.color", "descriptionFallback": "Default icon color. Inherits currentColor so the icon automatically matches surrounding text."}, {"type": "dimension", "value": "var(--origam-font__size---md)", "tokenPath": "--origam-icon---font-size-md", "descriptionKey": "components.ligature_icon.tokens.font_size_md", "descriptionFallback": "Font size for the default size 