gam-menu__item</text>\n  <circle cx=\"46\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"46\" y=\"28\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"46\" cy=\"68\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"46\" y=\"72\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"46\" cy=\"110\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"46\" y=\"114\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"46\" cy=\"152\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"46\" y=\"156\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"46\" cy=\"194\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"46\" y=\"198\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n", "code": "<origam-overlay role=\"menu\" v-model=\"isActive\">\n  <template #activator=\"{ props }\">\n    <slot name=\"activator\" v-bind=\"{ props }\"/>\n  </template>\n\n  <template #default>\n    <div class=\"origam-menu__content\">\n      <slot name=\"default\">\n        <origam-list class=\"origam-menu__list\">\n          <origam-list-subheader v-if=\"title\" class=\"origam-menu__title\">\n            {{ title }}\n          </origam-list-subheader>\n          <origam-list-group class=\"origam-menu__items\">\n            <origam-list-item\n              v-for=\"item in items\"\n              class=\"origam-menu__item\"\n              v-bind=\"item\"\n            />\n          </origam-list-group>\n        </origam-list>\n      </slot>\n    </div>\n  </template>\n</origam-overlay>", "legend": [{"cls": "#activator slot", "num": 1, "descriptionKey": "components.menu.anatomy.activator", "descriptionFallback": "The element that triggers the menu open/close. Receives an event-binding props object from the overlay."}, {"cls": ".origam-menu__list", "num": 2, "descriptionKey": "components.menu.anatomy.list", "descriptionFallback": "OrigamList container rendered inside the overlay panel (default slot fallback)."}, {"cls": ".origam-menu__title", "num": 3, "descriptionKey": "components.menu.anatomy.title", "descriptionFallback": "Optional OrigamListSubheader injected when the title prop is set."}, {"cls": ".origam-menu__items", "num": 4, "descriptionKey": "components.menu.anatomy.items", "descriptionFallback": "OrigamListGroup container iterating over the items array."}, {"cls": ".origam-menu__item", "num": 5, "descriptionKey": "components.menu.anatomy.item", "descriptionFallback": "Each OrigamListItem rendered from the items array. When an item has children, a nested OrigamMenu is rendered instead."}], "classes": [{"cls": "origam-menu", "descriptionKey": "components.menu.anatomy.root", "descriptionFallback": "Root class applied to the overlay element (role=\"menu\")."}, {"cls": "origam-menu__list", "descriptionKey": "components.menu.anatomy.list", "descriptionFallback": "OrigamList rendered as the default items container."}, {"cls": "origam-menu__title", "descriptionKey": "components.menu.anatomy.title", "descriptionFallback": "OrigamListSubheader rendered when title prop is set."}, {"cls": "origam-menu__items", "descriptionKey": "components.menu.anatomy.items", "descriptionFallback": "OrigamListGroup iterating over the items array."}, {"cls": "origam-menu__item", "descriptionKey": "components.menu.anatomy.item", "descriptionFallback": "Each OrigamListItem rendered per item in the items array."}], "svgDesc": "Schematic of the Menu component with 5 numbered parts.", "svgTitle": "Anatomy of OrigamMenu", "rootClass": "origam-menu", "figcaption": "Anatomy of <code>&lt;origam-menu&gt;</code> — 5 parts: activator (slot), content panel, optional title subheader, and list items (rendered from the items array or default slot).", "svgViewBox": "0 0 700 280"}, "cssVars": [{"name": "--origam-menu---background", "defaultValue": "{color.surface.raised}", "descriptionKey": "components.menu.css_vars.background", "descriptionFallback": "Menu panel background color."}, {"name": "--origam-menu---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.menu.css_vars.color", "descriptionFallback": "Menu text color."}, {"name": "--origam-menu---border-radius", "defaultValue": "{radius.md}", "descriptionKey": "components.menu.css_vars.border_radius", "descriptionFallback": "Border-radius of the menu panel."}, {"name": "--origam-menu---box-shadow", "defaultValue": "{shadow.lg}", "descriptionKey": "components.menu.css_vars.box_shadow", "descriptionFallback": "Drop shadow applied to the menu panel."}, {"name": "--origam-menu---max-height", "defaultValue": "calc(100vh - 32px)", "descriptionKey": "components.menu.css_vars.max_height", "descriptionFallback": "Maximum height before the menu becomes scrollable."}, {"name": "--origam-menu---z-index", "defaultValue": "{zIndex.dropdown}", "descriptionKey": "components.menu.css_vars.z_index", "descriptionFallback": "Z-index of the menu overlay panel."}, {"name": "--origam-menu---transition-duration", "defaultValue": "{motion.duration.fast}", "descriptionKey": "components.menu.css_vars.transition_duration", "descriptionFallback": "Enter/leave transition duration."}, {"name": "--origam-menu__content---padding", "defaultValue": "{space.1}", "descriptionKey": "components.menu.css_vars.content_padding", "descriptionFallback": "Inner padding of the menu content area."}, {"name": "--origam-menu__content---max-width", "defaultValue": "320px", "descriptionKey": "components.menu.css_vars.content_max_width", "descriptionFallback": "Maximum width of the menu content area."}], "playground": {"controls": [{"kind": "select", "prop": "location", "options": [{"label": "bottom", "value": "bottom"}, {"label": "top", "value": "top"}, {"label": "left", "value": "left"}, {"label": "right", "value": "right"}, {"label": "bottom start", "value": "bottom start"}, {"label": "bottom end", "value": "bottom end"}], "labelKey": "components.menu.playground.location", "defaultValue": "bottom", "labelFallback": "Location"}, {"kind": "switch", "prop": "closeOnContentClick", "labelKey": "components.menu.playground.close_on_content_click", "defaultValue": true, "labelFallback": "Close on content click"}, {"kind": "switch", "prop": "openOnHover", "labelKey": "components.menu.playground.open_on_hover", "defaultValue": false, "labelFallback": "Open on hover"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}, {"label": "xl", "value": "xl"}], "labelKey": "components.menu.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "select", "prop": "elevation", "options": [{"label": "(default)", "value": ""}, {"label": "0", "value": "0"}, {"label": "sm", "value": "sm"}, {"label": "md", "value": "md"}, {"label": "lg", "value": "lg"}], "labelKey": "components.menu.playground.elevation", "defaultValue": "", "labelFallback": "Elevation"}]}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('12138fa8-dca6-43f1-a615-b1931bcf102e', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'component', 'messages', 'Messages', 'Form & Input', NULL, 'mdi-message-text-outline', 'components.catalog.messages.description', 'Accessible live region that displays a list of validation or hint messages below form fields. Supports transitions, custom slot content, and full design token customisation.', NULL, NULL, 'origam-messages', NULL, 'packages/ds/src/components/Messages/OrigamMessages.vue', 'origam', NULL, NULL, '/stories/?story=components-messages--design', '/docs/components/Messages/OrigamMessages.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.messages.a11y.live_region", "noteFallback": "The root element carries aria-live=\"polite\" and role=\"status\". Screen readers announce new messages without interrupting the current speech flow."}, {"noteKey": "components.messages.a11y.color_note", "noteFallback": "Color alone is never the sole indicator — message text is always visible. Ensure sufficient contrast ratio (≥4.5:1) when overriding the color prop."}], "roles": ["status"], "keyboard": []}, "tokens": {"excerpt": [{"type": "color", "value": "currentColor", "tokenPath": "--origam-messages---color", "descriptionKey": "components.messages.tokens.color", "descriptionFallback": "Inherits the field context color (error=danger, hint=info)."}, {"type": "dimension", "value": "12px", "tokenPath": "--origam-messages---font-size", "descriptionKey": "components.messages.tokens.font_size", "descriptionFallback": "Fixed 12 px per design spec."}, {"type": "dimension", "value": "14px", "tokenPath": "--origam-messages---min-height", "descriptionKey": "components.messages.tokens.min_height", "descriptionFallback": "Prevents layout collapse when messages array is empty."}, {"type": "duration", "value": "var(--origam-motion__duration---normal)", "tokenPath": "--origam-messages__message---transition-duration", "descriptionKey": "components.messages.tokens.message_transition", "descriptionFallback": "Slide-y transition duration for individual message rows."}], "sourceFile": "packages/ds/src/assets/css/tokens/light.css"}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"180\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"30\" width=\"640\" height=\"120\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.3))\" stroke-width=\"1.5\"/>\n  <rect x=\"50\" y=\"52\" width=\"580\" height=\"26\" rx=\"3\" fill=\"var(--origam-color__feedback--danger---bgSubtle, rgba(239,68,68,0.06))\"/>\n  <text x=\"340\" y=\"69\" font-size=\"9\" fill=\"var(--origam-color__feedback--danger---fg, #dc2626)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-messages__message — \"This field is required\"</text>\n  <rect x=\"50\" y=\"84\" width=\"580\" height=\"26\" rx=\"3\" fill=\"var(--origam-color__feedback--danger---bgSubtle, rgba(239,68,68,0.04))\"/>\n  <text x=\"340\" y=\"101\" font-size=\"9\" fill=\"var(--origam-color__feedback--danger---fg, #dc2626)\" text-anchor=\"middle\" font-family=\"''JetBrains Mono'',monospace\">origam-messages__message — \"Must be a valid email\"</text>\n  <circle cx=\"26\" cy=\"34\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"26\" y=\"38\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"26\" cy=\"56\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"26\" y=\"60\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"26\" cy=\"88\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"26\" y=\"92\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n", "code": "<div\n  class=\"origam-messages\"\n  aria-live=\"polite\"\n  role=\"status\"\n>\n  <transition-group name=\"slide-y-transition\">\n    <div\n      v-for=\"message in normalizedMessages\"\n      :key=\"message\"\n      class=\"origam-messages__message\"\n    >\n      <slot :message=\"message\">{{ message }}</slot>\n    </div>\n  </transition-group>\n</div>", "legend": [{"cls": ".origam-messages", "num": 1, "descriptionKey": "components.messages.anatomy.root", "descriptionFallback": "Root container. Has aria-live=\"polite\" and role=\"status\" for screen-reader announcements."}, {"cls": ".origam-messages__message (row 1)", "num": 2, "descriptionKey": "components.messages.anatomy.message_1", "descriptionFallback": "First message row. Enters/leaves with the slide-y transition."}, {"cls": ".origam-messages__message (row n)", "num": 3, "descriptionKey": "components.messages.anatomy.message_n", "descriptionFallback": "Subsequent message rows — one per entry in the messages array."}], "classes": [{"cls": "origam-messages", "descriptionKey": "components.messages.anatomy.root", "descriptionFallback": "Root container — aria-live=\"polite\" + role=\"status\" live region."}, {"cls": "origam-messages__message", "descriptionKey": "components.messages.anatomy.message", "descriptionFallback": "Individual message row. One per string in the messages prop."}], "svgDesc": "Schematic of the Messages component with 3 numbered parts.", "svgTitle": "Anatomy of OrigamMessages", "rootClass": "origam-messages", "figcaption": "Anatomy of <code>&lt;origam-messages&gt;</code> — 3 parts: the root live-region container, and one <code>__message</code> row per entry in the messages array.", "svgViewBox": "0 0 700 180"}, "cssVars": [{"name": "--origam-messages---color", "defaultValue": "currentColor", "descriptionKey": "components.messages.css_vars.color", "descriptionFallback": "Default message text color. Inherits from the parent context (OrigamField injects the error/hint color)."}, {"name": "--origam-messages---font-size", "defaultValue": "12px", "descriptionKey": "components.messages.css_vars.font_size", "descriptionFallback": "Font size of all message rows (fixed 12 px per spec)."}, {"name": "--origam-messages---min-height", "defaultValue": "14px", "descriptionKey": "components.messages.css_vars.min_height", "descriptionFallback": "Minimum height preserved even with no messages, preventing layout jump."}, {"name": "--origam-messages---opacity", "defaultValue": "{opacity.87}", "descriptionKey": "components.messages.css_vars.opacity", "descriptionFallback": "Container opacity."}, {"name": "--origam-messages__message---transition-duration", "defaultValue": "{motion.duration.normal}", "descriptionKey": "components.messages.css_vars.message_transition", "descriptionFallback": "Duration of the slide-y enter/leave transition per message row."}], "playground": {"controls": [{"kind": "select", "prop": "color", "options": [{"label": "(none)", "value": ""}, {"label": "primary", "value": "primary"}, {"label": "secondary", "value": "secondary"}, {"label": "success", "value": "success"}, {"label": "danger", "value": "danger"}, {"label": "warning", "value": "warning"}, {"label": "info", "value": "info"}], "labelKey": "components.messages.playground.color", "defaultValue": "", "labelFallback": "Color / Intent"}, {"kind": "select", "prop": "density", "options": [{"label": "(default)", "value": ""}, {"label": "default", "value": "default"}, {"label": "DENSITY.DEFAULT", "value": "DENSITY.DEFAULT"}, {"label": "compact", "value": "compact"}, {"label": "DENSITY.COMPACT", "value": "DENSITY.COMPACT"}, {"label": "DENSITY.COMFORTABLE", "value": "DENSITY.COMFORTABLE"}, {"label": "comfortable", "value": "comfortable"}], "labelKey": "components.messages.playground.density", "defaultValue": "", "labelFallback": "Density"}, {"kind": "select", "prop": "rounded", "options": [{"label": "(default)", "value": ""}, {"label": "ROUNDED.X_SMALL", "value": "ROUNDED.X_SMALL"}, {"label": "x-small", "value": "x-small"}, {"label": "ROUNDED.SMALL", "value": "ROUNDED.SMALL"}, {"label": "small", "value": "small"}, {"label": "default", "value": "default"}, {"label": "ROUNDED.DEFAULT", "value": "ROUNDED.DEFAULT"}, {"label": "ROUNDED.MEDIUM", "value": "ROUNDED.MEDIUM"}, {"label": "medium", "value": "medium"}, {"label": "large", "value": "large"}, {"label": "ROUNDED.LARGE", "value": "ROUNDED.LARGE"}, {"label": "x-large", "value": "x-large"}, {"label": "ROUNDED.X_LARGE", "value": "ROUNDED.X_LARGE"}, {"label": "shaped", "value": "shaped"}, {"label": "ROUNDED.SHAPED", "value": "ROUNDED.SHAPED"}, {"label": "shaped-invert", "value": "shaped-invert"}, {"label": "ROUNDED.SHAPED_INVERT", "value": "ROUNDED.SHAPED_INVERT"}], "labelKey": "components.messages.playground.rounded", "defaultValue": "", "labelFallback": "Rounded"}, {"kind": "switch", "prop": "active", "labelKey": "components.messages.playground.active", "defaultValue": false, "labelFallback": "Active"}], "defaultSlotContent": "Content"}, "previewVariants": []}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('de0682d2-c6d6-4af3-b781-4f42f9acae9e', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'component', 'number-field', 'NumberField', 'Form & Input', NULL, 'mdi-numeric', 'components.catalog.number_field.description', 'Numeric input field with built-in increment/decrement controls, min/max/step clamping, precision formatting, hold-to-repeat, split layout, and full form validation support.', NULL, NULL, 'origam-number-field', NULL, 'packages/ds/src/components/NumberField/OrigamNumberField.vue', 'origam', NULL, NULL, '/stories/?story=components-numberfield--design', '/docs/components/NumberField/OrigamNumberField.html', NULL, '{"a11y": {"notes": [{"noteKey": "components.number_field.a11y.group_note", "noteFallback": "The control container has role=\"group\" and aria-label matching the field label, grouping the input + buttons semantically."}, {"noteKey": "components.number_field.a11y.button_labels", "noteFallback": "Increment and decrement buttons have aria-label=\"Increment\" and aria-label=\"Decrement\" respectively. They also have aria-hidden=\"true\" on their icon children."}, {"noteKey": "components.number_field.a11y.disabled_note", "noteFallback": "When value reaches min or max, the corresponding button is disabled (pointer-events: none, aria-disabled=\"true\")."}], "roles": ["group", "spinbutton"], "keyboard": [{"key": "ArrowUp", "actionKey": "components.number_field.a11y.key_increment", "actionFallback": "Increments the value by step."}, {"key": "ArrowDown", "actionKey": "components.number_field.a11y.key_decrement", "actionFallback": "Decrements the value by step."}, {"key": "Tab", "actionKey": "components.number_field.a11y.key_tab", "actionFallback": "Moves focus to the next interactive element (input → increment → decrement)."}]}, "anatomy": {"svg": "\n  <rect x=\"0\" y=\"0\" width=\"700\" height=\"200\" fill=\"var(--origam-color__surface---sunken, #fbf5ff)\" rx=\"4\"/>\n  <rect x=\"30\" y=\"20\" width=\"640\" height=\"60\" rx=\"4\" fill=\"var(--origam-color__surface---raised, #fff)\" stroke=\"var(--origam-color__border---default, rgba(124,58,237,0.4))\" stroke-width=\"1.5\"/>\n  <text x=\"60\" y=\"37\" font-size=\"8\" fill=\"var(--origam-color__text---secondary, #7c3aed)\" font-family=\"''JetBrains Mono'',monospace\">Quantity</text>\n  <rect x=\"60\" y=\"44\" width=\"480\" height=\"24\" rx=\"3\" fill=\"var(--origam-color__action--primary---bgSubtle, rgba(124,58,237,0.04))\"/>\n  <text x=\"80\" y=\"60\" font-size=\"10\" fill=\"var(--origam-color__text---primary, #111)\" font-family=\"''JetBrains Mono'',monospace\">5</text>\n  <rect x=\"560\" y=\"24\" width=\"48\" height=\"52\" rx=\"3\" fill=\"var(--origam-color__action--secondary---bgHover, rgba(124,58,237,0.08))\" stroke=\"var(--origam-color__border---default, rgba(168,85,247,0.3))\" stroke-width=\"1\"/>\n  <text x=\"584\" y=\"38\" font-size=\"14\" fill=\"var(--origam-color__text---primary, #7c3aed)\" text-anchor=\"middle\">+</text>\n  <text x=\"584\" y=\"64\" font-size=\"14\" fill=\"var(--origam-color__text---primary, #7c3aed)\" text-anchor=\"middle\">−</text>\n  <rect x=\"30\" y=\"90\" width=\"640\" height=\"26\" rx=\"3\" fill=\"transparent\"/>\n  <text x=\"60\" y=\"107\" font-size=\"8\" fill=\"var(--origam-color__text---tertiary, #9ca3af)\" font-family=\"''JetBrains Mono'',monospace\">origam-messages__message — hint text</text>\n  <circle cx=\"26\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"26\" y=\"28\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">1</text>\n  <circle cx=\"26\" cy=\"90\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"26\" y=\"94\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">2</text>\n  <circle cx=\"550\" cy=\"24\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"550\" y=\"28\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">3</text>\n  <circle cx=\"550\" cy=\"42\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"550\" y=\"46\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">4</text>\n  <circle cx=\"550\" cy=\"62\" r=\"9\" fill=\"var(--origam-color__action--primary---bgHover, #a855f7)\"/>\n  <text x=\"550\" y=\"66\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">5</text>\n  <circle cx=\"26\" cy=\"52\" r=\"9\" fill=\"var(--origam-color__action--primary---bg, #7c3aed)\"/>\n  <text x=\"26\" y=\"56\" font-size=\"8\" fill=\"#fff\" text-anchor=\"middle\" font-weight=\"700\">6</text>\n", "code": "<origam-field class=\"origam-number-field\">\n  <!-- outer prepend / append slots -->\n  <slot name=\"prepend\"/>\n\n  <!-- field composite: label + input + inner icons + controls -->\n  <slot name=\"field\">\n    <!-- label, prefix, input, suffix are managed by OrigamInput -->\n    <div class=\"origam-number-field__control\" role=\"group\" :aria-label=\"label\">\n      <!-- decrement (split-left or stacked-bottom) -->\n      <origam-btn aria-label=\"Decrement\" @click=\"decrement\" />\n\n      <!-- native <input type=\"number\"> -->\n      <input class=\"origam-number-field__compact-input\" :aria-label=\"label\" />\n\n      <!-- increment (split-right or stacked-top) -->\n      <origam-btn aria-label=\"Increment\" @click=\"increment\" />\n    </div>\n  </slot>\n\n  <slot name=\"append\"/>\n\n  <!-- details: messages + counter -->\n  <slot name=\"details\">\n    <origam-messages :messages=\"errorMessages\" />\n  </slot>\n</origam-field>", "legend": [{"cls": ".origam-number-field", "num": 1, "descriptionKey": "components.number_field.anatomy.root", "descriptionFallback": "Root OrigamField container. Holds the label, input area, and details zone."}, {"cls": ".origam-messages (details slot)", "num": 2, "descriptionKey": "components.number_field.anatomy.messages", "descriptionFallback": "Details zone below the field — renders hint, error messages, and counter."}, {"cls": ".origam-number-field__control", "num": 3, "descriptionKey": "components.number_field.anatomy.control", "descriptionFallback": "Wrapper for the stacked or split increment/decrement buttons."}, {"cls": ".origam-number-field__compact-input", "num": 4, "descriptionKey": "components.number_field.anatomy.compact_input", "descriptionFallback": "Compact-mode inner input shown between the stacked controls."}, {"cls": "increment button", "num": 5, "descriptionKey": "components.number_field.anatomy.increment", "descriptionFallback": "Increment (+) button. aria-label=\"Increment\". Disabled when value >= max."}, {"cls": "decrement button", "num": 6, "descriptionKey": "components.number_field.anatomy.decrement", "descriptionFallback": "Decrement (−) button. aria-label=\"Decrement\". Disabled when value <= min."}], "classes": [{"cls": "origam-number-field", "descriptionKey": "components.number_field.anatomy.root", "descriptionFallback": "Root field container."}, {"cls": "origam-number-field__control", "descriptionKey": "components.number_field.anatomy.control", "descriptionFallback": "Wrapper for the increment/decrement controls (role=\"group\")."}, {"cls": "origam-number-field__compact-input", "descriptionKey": "components.number_field.anatomy.compact_input", "descriptionFallback": "Input element shown between stacked controls in compact mode."}], "svgDesc": "Schematic of the NumberField component with 6 numbered parts.", "svgTitle": "Anatomy of OrigamNumberField", "rootClass": "origam-number-field", "figcaption": "Anatomy of <code>&lt;origam-number-field&gt;</code> — 6 parts: root field, input area, control container, increment button, decrement button, and messages/details row.", "svgViewBox": "0 0 700 200"}, "cssVars": [{"name": "--origam-number-field---background-color", "defaultValue": "{color.surface.default}", "descriptionKey": "components.number_field.css_vars.background_color", "descriptionFallback": "Field background color."}, {"name": "--origam-number-field---color", "defaultValue": "{color.text.primary}", "descriptionKey": "components.number_field.css_vars.color", "descriptionFallback": "Field text color."}, {"name": "--origam-number-field---border-color", "defaultValue": "{color.border.default}", "descriptionKey": "components.number_field.css_vars.border_color", "descriptionFallback": "Default border color. Overridden to focus / error variants on interaction."}, {"name": "--origam-number-field---border-radius", "defaultValue": "{radius.sm}", "descriptionKey": "components.number_field.css_vars.border_radius", "descriptionFallback": "Border-radius of the field container."}, {"name": "--origam-number-field---opacity-disabled", "defaultValue": "{opacity.50}", "descriptionKey": "components.number_field.css_vars.opacity_disabled", "descriptionFallback": "Opacity applied when disabled=true."}, {"name": "--origam-number-field__increment---background-color-hover", "defaultValue": "{color.action.secondary.bgHover}", "descriptionKey": "components.number_field.css_vars.increment_bg_hover", "descriptionFallback": "Background of the increment button on hover."}, {"name": "--origam-number-field__decrement---background-color-hover", "defaultValue": "{color.action.secondary.bgHover}", "descriptionKey": "components.number_field.css_vars.decrement_bg_hover", "descriptionFallback": "Background of the decrement button on hover."}], "playground": {"controls": [{"kind": "number", "prop": "modelValue", "labelKey": "components.number_field.playground.model_value", "defaultValue": 5, "labelFallback": "Value"}, {"kind": "number", "prop": "min", "labelKey": "components.number_field.playground.min", "defaultValue": 0, "labelFallback": "Min"}, {"kind": "number", "prop": "max", "labelKey": "components.number_field.playground.max", "defaultValue": 100, "labelFallback": "Max"}, {"kind": "number", "prop": "step", "labelKey": "components.number_field.playground.step", "defaultValue": 1, "labelFallback": "Step"}, {"kind": "switch", "prop": "split", "labelKey": "components.number_field.playground.split", "defaultValue": false, "labelFallback": "Split layout"}, {"kind": "switch", "prop": "compact", "labelKey": "components.number_field.playground.compact", "defaultValue": false, "labelFallback": "Compact"}, {"kind": "switch", "prop": "disabled", "labelKey": "components.number_field.playground.disabled", "defaultValue": false, "labelFallback": "Disabled"}, {"kind": "select", "prop": "variant", "options": [{"label": "outlined", "value": "outlined"}, {"label": "filled", "value": "filled"}, {"label": "underlined", "value": "underlined"}, {"label": "solo", "value": "solo"}, {"label": "plain", "value": "plain"}], "labelKey": "components.number_field.playground.variant", "defaultValue": "outlined", "labelFallback": "Variant"}]}, "previewVariants": [{"label": "default", "props": {"max": 100, "min": 0, "label": "Quantity", "modelValue": 5}}, {"label": "split", "props": {"label": "Price", "split": true, "modelValue": 19}}, {"label": "compact", "props": {"max": 99, "min": 1, "label": "Count", "compact": true, "modelValue": 3}}, {"label": "disabled", "props": {"label": "Disabled", "disabled": true, "modelValue": 10}}]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
