scriptionFallback": "Leading icon wrapper. Only rendered when icon prop is provided."}, {"cls": "origam-tab__label", "descriptionKey": "components.tab.anatomy.label", "descriptionFallback": "Label zone containing the default slot content or text prop."}, {"cls": "origam-tab__append", "descriptionKey": "components.tab.anatomy.append", "descriptionFallback": "Trailing icon wrapper. Only rendered when appendIcon prop is provided."}, {"cls": "origam-tab__indicator", "descriptionKey": "components.tab.anatomy.indicator", "descriptionFallback": "Bottom indicator bar. Visible only in underline variant; scales on activation."}], "svgDesc": "Schematic of the Tab component with 4 numbered internal parts.", "svgTitle": "Anatomy of OrigamTab", "rootClass": "origam-tab", "figcaption": "Anatomy of <code>&lt;origam-tab&gt;</code> — 5 internal parts. The indicator (⑤) is absolute-positioned at the block-end and scales on activation.", "svgViewBox": "0 0 600 200"}, "cssVars": [{"name": "--origam-tabs__item---color", "defaultValue": "{color.text.secondary}", "descriptionKey": "components.tab.css_vars.color", "descriptionFallback": "Tab label color in resting state."}, {"name": "--origam-tabs__item---background-color", "defaultValue": "transparent", "descriptionKey": "components.tab.css_vars.background_color", "descriptionFallback": "Tab background in resting state."}, {"name": "--origam-tabs__item---height", "defaultValue": "48px", "descriptionKey": "components.tab.css_vars.height", "descriptionFallback": "Minimum tab height."}, {"name": "--origam-tabs__item---padding-inline", "defaultValue": "16px", "descriptionKey": "components.tab.css_vars.padding_inline", "descriptionFallback": "Horizontal padding of each tab."}, {"name": "--origam-tabs__item---padding-block", "defaultValue": "0", "descriptionKey": "components.tab.css_vars.padding_block", "descriptionFallback": "Vertical padding of each tab."}, {"name": "--origam-tabs__item---gap", "defaultValue": "8px", "descriptionKey": "compone