INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d2733cb5-3cfb-4175-8731-a86fe9b8d4da', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-clipboard', 'useClipboard', NULL, 'Clipboard', 'mdi-clipboard-outline', '', 'Headless clipboard composable. Wraps the modern navigator.clipboard.writeText API with a legacy execCommand fallback. Exposes a self-resetting copied flag so consumers do not need to wire the reset timeout themselves. Never throws — callers branch on the returned boolean.', NULL, 'function useClipboard(options?: IUseClipboardOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('8c9e2869-a7f7-4042-b6e4-848408115b41', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-code', 'useCode', NULL, 'Code', 'mdi-code-tags', '', 'Singleton shiki-powered syntax highlighter. Lazily loads shiki on the first highlight() call to keep the initial bundle small. Bundles only the curated origam language subset and dual light/dark themes so token colours switch via CSS variables without re-tokenising. Caches results in a tiny LRU keyed by (code, lang).', NULL, 'function useCode(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('036aa713-181f-4cc5-a51a-7d5301a988f4', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-color', 'useColor', NULL, 'Commons', 'mdi-palette', '', 'Resolve background and text colors from intent tokens or raw CSS values. Part of the classes-first strategy: tokenised intents emit utility classes, custom hex/rgb values emit inline styles.', NULL, 'function useColor(
