INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('f66fbc4b-6edb-45f7-a90b-cb0d80f36036', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-padding', 'usePadding', NULL, 'Commons', 'mdi-arrow-collapse-all', '', 'Resolves the `padding` shorthand prop into utility classes for spacing-scale steps (0–12) or inline padding declarations for custom values. Mirror of useMargin for the padding axis.', NULL, 'function usePadding(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('522308cd-1349-4e27-945c-7f096e951bd5', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-paginated-items', 'usePaginatedItems', 'DataTable', 'DataTable', NULL, NULL, NULL, NULL, 'function usePaginatedItems(options: { items: Ref<readonly (T | IDataTableGroup<T>)[]> startIndex: Ref<number> stopIndex: Ref<number> itemsPerPage: Ref<number> }): { paginatedItems: ComputedRef<readonly (T | IDataTableGroup<T>)[]>; }', NULL, NULL, 'packages/ds/src/composables/DataTable/paginatedItems.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('04af482b-968a-4b10-be0e-8b3d1553e7fe', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-pagination', 'usePagination', NULL, 'DataTable', 'mdi-book-open-page-variant-outline', '', 'Suite of three pagination helpers for OrigamDataTable: createPagination initialises page and itemsPerPage refs from props; providePagination computes derived state (startIndex, stopIndex, pageCount) and provides it to children; usePagination injects the provided pagination context. A fourth helper usePaginatedItems slices the items array for the current page.', NULL, '// Initialise pagination refs from props
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('14a072bf-5cc3-4439-97e3-37b1114a8cc4', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-parallax', 'useParallaxRuntime', NULL, 'Parallax', 'mdi-layers-triple-outline', '', 'Headless parallax engine used by OrigamParallax. Maintains a registry of layers, tracks scroll progress via IntersectionObserver, and drives per-frame transforms via requestAnimationFrame. Branches automatically to a CSS scroll-driven animation path (Chrome 115+) when the easing is linear and the browser supports animation-timeline: scroll(). Respects prefers-reduced-motion at OS level.', NULL, 'function useParallaxRuntime(options: IUseParallaxRuntimeOptions): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('655e75bd-8c91-434b-9769-e6fba5a407e2', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-parallax-transform', 'useParallaxTransform', NULL, 'Parallax', 'mdi-layers-triple-outline', '', 'Computes CSS transform strings for parallax layer elements based on normalised mouse-position coordinates. Supports five transform types: translate, rotate, depth (3-D tilt), depth-inv (inverted tilt), scale, scale-x, and scale-y. Consumed by OrigamParallax to animate child layers.', NULL, 'function useParallaxTransform(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('c8e58242-9911-4cc1-afc4-13131971ad25', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-passed-props', 'usePassedProps', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function usePassedProps(_props: T, instanceLabel?: string = ''usePassedProps''): (key: Extract<keyof T, string> | string) => boolean', NULL, NULL, 'packages/ds/src/composables/Commons/passedProps.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('364d25e0-11a9-4f7d-bde0-ac207d38cde7', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-password-strength', 'computeStrength', NULL, 'PasswordField', 'mdi-shield-lock-outline', '', 'Pure function (no Vue reactivity needed) that scores a password string on a 0-4 scale based on length, digit presence, case diversity, and special characters. Returns a numeric score and a semantic level (weak / fair / good / strong). Used internally by OrigamPasswordField to drive the strength bar colour and label. No third-party dependencies.', NULL, 'function computeStrength(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0a347b25-59bc-43ad-b951-c6d7dd7e2b45', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-position', 'usePosition', NULL, 'Commons', 'mdi-map-marker-outline', '', 'Derives CSS positioning classes and inline style declarations from IPositionProps. Emits a BEM modifier class for the position variant (absolute, fixed, sticky, relative, static) and inline top/bottom/left/right properties for any offset props that are set.', NULL, 'function usePosition(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0624d0f8-87bb-48a1-87b5-cc5715398d3d', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-progress', 'useProgress', NULL, 'Progress', 'mdi-progress-clock', '', 'Computes all state needed to render a progress bar or circular progress indicator: a normalised 0-100 value from modelValue and max, thickness as a number, a visibility flag tied to IntersectionObserver, and BEM class/style arrays that handle indeterminate, striped, active, and absolute modes. Used by OrigamProgressLinear and OrigamProgressCircular.', NULL, 'function useProgress(props: IProgressTypeProps): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('baaa5429-347d-4717-bbce-b94e90086565', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-props', 'useProps', NULL, 'Commons', 'mdi-tune-variant', '', 'Returns a filterProps utility that picks only the keys declared on a component interface from an arbitrary props object, stripping undefined values so that Vue 3 boolean-prop coercion does not silently override withDefaults in child components. Used by composite components (DataTable, List, Select…) to forward a safe subset of their own props to child Origam components.', NULL, 'function useProps<T extends Record<string, any>>(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('95f24071-74a2-4895-a4d4-471b70504de0', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-qr-code', 'useQrCode', NULL, 'QrCode', 'mdi-qrcode', '', 'Headless QR-code composable. Encodes a string payload using qrcode-generator (Reed-Solomon + matrix masking) and returns a reactive SVG string, the raw module matrix, and the matrix size. The encoder is LRU-cached at module level to avoid rebuilding identical matrices on re-renders. Fully SSR-safe — no DOM API is touched.', NULL, 'function useQrCode(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4115836f-717a-4f18-85f0-2ffb8a80e849', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-refs', 'useRefs', NULL, 'Commons', 'mdi-link-variant', '', 'Manages a dynamic array of template refs that is reset before each update cycle. Provides an updateRef(el, i) callback designed for use with :ref in v-for loops, where Vue replaces individual refs by index. The refs array is always fresh (cleared in onBeforeUpdate) so stale elements from a previous render do not leak.', NULL, 'function useRefs<T extends object>(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('af7daea2-f630-4f33-bf8f-cd028c4b62a1', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-resize-observer', 'useResizeObserver', NULL, 'Commons', 'mdi-resize', '', 'Wraps the native ResizeObserver API with a reactive template ref. Returns a resizeRef to attach to any element and a readonly contentRect that updates on every resize. Automatically disconnects the observer on component unmount. Supports both content-box (default) and border-box measurement.', NULL, 'function useResizeObserver(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('abfeff96-1886-46cd-b546-f1db399df791', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-rounded', 'useRounded', NULL, 'Commons', 'mdi-rounded-corner', '', 'Resolves the `rounded` prop to border-radius classes and inline styles. Supports the modern utility taxonomy (xs/sm/md/lg/xl/none/full), the legacy named variants (x-small/small/default/medium/large/x-large/shaped), numbers and free-form CSS values.', NULL, 'function useRounded(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0ee922f7-bea5-4815-b436-e67eecae12bb', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-route', 'useRoute', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useRoute(): Ref<RouteLocationNormalizedLoaded | undefined>', NULL, NULL, 'packages/ds/src/composables/Commons/route.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d9f14d84-19dc-4776-805f-27cfc33885ec', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-router', 'useRouter', NULL, 'Commons', 'mdi-routes', '', 'Thin wrappers around Vue Router that expose the current route and router instance from the Vue component instance rather than via direct vue-router import. Also provides useLink (a link-resolution helper used by all clickable Origam components) and useBackButton (navigation guard for hardware/browser back button interception).', NULL, '// Returns the active route as a reactive ref
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('626831f1-8d4e-4eba-ae52-17c13b6afbf0', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-rtl', 'useRtl', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useRtl(name?: string = getCurrentInstanceName()): { isRtl: Ref<boolean, boolean>; rtlClasses: ComputedRef<string>; }', NULL, NULL, 'packages/ds/src/composables/Commons/rtl.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4a2ba96e-5858-46a2-b435-c777be65fee5', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-scope-id', 'useScopeId', NULL, 'Commons', 'mdi-identifier', '', 'Reads the Vue SFC scope ID from the current component instance and returns it as an attribute object. Used to ensure that teleported or dynamically-created DOM nodes receive the same scoped-CSS attribute as their parent component, so that scoped style rules continue to match across teleport boundaries.', NULL, 'function useScopeId(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('1d3026c1-d042-42ae-9b9f-844b38b0f7c4', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-scroll', 'useScroll', NULL, 'Commons', 'mdi-gesture-swipe-vertical', '', 'Tracks scroll position and direction on a configurable target element (or window). Returns reactive flags for scroll direction, activity state, threshold crossing, and a scroll ratio useful for progressive UI transitions. Also exposes useScrollStrategies (apply named scroll behaviours like block, close, or reposition to floating overlays) and useScrolling (keyboard + scroll helpers for virtualised list + search-field combos).', NULL, 'function useScroll(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('842e14d8-89ec-4459-87ea-6dd864527428', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-scrolling', 'useScrolling', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useScrolling(listRef: Ref<TOrigamList | undefined>, textFieldRef: Ref<TOrigamTextField | undefined>): { onListScroll: () => void; onListKeydown: (e: KeyboardEvent) => Promise<void>; }', NULL, NULL, 'packages/ds/src/composables/Commons/scrolling.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('60701d95-ea0c-4061-8da7-e04b499fe05e', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-select', 'useSelection', NULL, 'DataTable', 'mdi-checkbox-multiple-marked-outline', '', 'Inject accessor for the row-selection context provided by provideSelection inside OrigamDataTable. Returns the reactive selected Set and the select / toggleSelect / selectAll helpers plus status flags (someSelected, allSelected, showSelectAll). Used by checkbox columns and the header select-all control.', NULL, 'function useSelection(): IDataTableProvideSelection', NULL, NULL, 'packages/ds/src/composables/DataTable/select.composable.ts', NULL, NULL, 'useSelection throws when called outside a DataTable context (no inject match for ORIGAM_DATA_TABLE_SELECT_KEY). It must be used inside a component tree where provideSelection() was called by the parent table.', NULL, NULL, NULL, '{"consumedInterfaces": ["IDataTableProvideSelection", "IDataTableSelectableItem", "IDataTableSelectProps"]}', false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('aa48deac-5d08-4a46-b9c7-334082ab123f', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-select-link', 'useSelectLink', NULL, 'Commons', 'mdi-link-variant', '', 'Bridges a router link and a group selection: when the link becomes active (current route matches), it automatically selects its group item. Used internally by navigation components (NavList, BottomNav, Tabs) so that a hard navigation or a programmatic router push keeps the selected state in sync without a manual v-model update.', NULL, 'function useSelectLink(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('44bfeb7c-2cd2-4e82-bb08-0e84769125f3', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-sheet-swipe', 'useSheetSwipe', NULL, 'Sheet', 'mdi-gesture-swipe-up', '', 'Encapsulates bottom-sheet swipe gesture logic using Pointer Events (covers both mouse and touch). Tracks pointerdown → pointermove → pointerup on a dedicated handle element, resolves the target snap point on release via velocity (fast flick = step one snap) or absolute distance (slow drag = nearest snap), and exposes reactive drag state for 1:1 finger tracking during the gesture.', NULL, 'function useSheetSwipe(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('ea54b46f-025b-4d92-b5e0-47975c98e56d', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-size', 'useSize', NULL, 'Commons', 'mdi-magnify-plus-outline', '', 'Resolves the `size` prop to component-local modifier classes and optional width/height inline styles. Named presets (x-small/small/default/large/x-large) emit BEM modifier classes; custom values emit pixel dimensions.', NULL, 'function useSize(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('040b47ba-a8d1-431d-999b-ed4080751b40', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-slider-field', 'useSteps', NULL, 'SliderField', 'mdi-tune-variant', '', 'Pure-function stepping math for OrigamSliderField. Computes reactive min / max / step / decimals values from the component props and exposes a roundValue helper that snaps any raw number to the nearest valid step (clamped to [min, max]). After the migration to a native <input type="range">, this is the only remaining logic layer for the slider — the browser now owns drag tracking.', NULL, 'function useSteps(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0319b081-3ae7-4a52-b74d-d5797c7686ca', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-snackbar', 'useCountdown', NULL, 'Snackbar', 'mdi-timer-sand', '', 'Internal countdown timer used by OrigamSnackbar to drive the auto-dismiss progress indicator. Counts down from a given millisecond value using setInterval, ticking at the CSS transition duration of the host element so the progress bar remains visually synchronised. Exposes clear / reset / start controls and a reactive time ref.', NULL, 'function useCountdown(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e1063143-1660-44e8-a8ec-674c0d260948', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-snackbar-group', 'useSnackbarGroup', NULL, 'Snackbar', 'mdi-bell-outline', '', 'Module-level singleton store for a named snackbar stack. Push notifications via notify(), dismiss them by id or all at once. Each call sharing the same id option reads and writes the same reactive items list — the composable and the matching <OrigamSnackbarGroup id="…"> component share live state with no event bus required.', NULL, 'function useSnackbarGroup(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('e56b9e1e-e3b0-4c02-a387-fa69143d9b92', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-snackbar-group-internal', 'useSnackbarGroupInternal', 'Snackbar', 'Snackbar', NULL, NULL, NULL, NULL, 'function useSnackbarGroupInternal(id?: MaybeRefOrGetter<string> = SNACKBAR_GROUP_DEFAULT_ID): { rawItems: ComputedRef<ISnackbarGroupItem[]>; itemCount: ComputedRef<number>; registerDefaultDuration: (duration: number) => void; }', NULL, NULL, 'packages/ds/src/composables/Snackbar/snackbarGroupInternal.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0eda05ed-bca1-40ee-b3a8-7242d934ae15', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'const', 'blockquote-langs', 'BLOCKQUOTE_LANGS', 'Typography', NULL, NULL, 'consts.catalog.blockquote_langs.description', 'Closed list of valid lang values for OrigamBlockquote. Controls which decorative quote glyphs are rendered. ''auto'' detects the page language at runtime.', 'export const BLOCKQUOTE_LANGS: ReadonlyArray<TBlockquoteLang> = Object.values(BLOCKQUOTE_LANG)', NULL, NULL, 'Object.values(BLOCKQUOTE_LANG)', 'packages/ds/src/consts/Blockquote/blockquote.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('51d5f35e-393a-41d1-9abe-4989f044292d', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-sort', 'useSort', NULL, 'DataTable', 'mdi-sort', '', 'Inject accessor for the sort context provided by provideSort inside OrigamDataTable. Returns the reactive sortBy array and the toggleSort / isSorted helpers. Used by header cells to read and update the active sort columns. The companion useSortedItems applies the sort order to a reactive item list.', NULL, 'function useSort(): IDataTableProvideSort
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('df2ccbcb-c85c-4185-8dd4-10fd2d50afe2', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-sorted-items', 'useSortedItems', 'DataTable', 'DataTable', NULL, NULL, NULL, NULL, 'function useSortedItems(props: { customKeySort: TDataTableCompareFunction | undefined }, items: Ref<T[]>, sortBy: Ref<Array<IDataTableSortItem>>, options?: { transform?: (item: T) => Record<string, unknown> sortFunctions?: Ref<Record<string, TDataTableCompareFunction> | undefined> sortRawFunctions?: Ref<Record<string, TDataTableCompareFunction> | undefined> }): { sortedItems: ComputedRef<T[]>; }', NULL, NULL, 'packages/ds/src/composables/DataTable/sortedItems.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('6f88f7e1-33c3-46bf-838e-dd34ee42a30b', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-ssr-boot', 'useSsrBoot', NULL, 'Commons', 'mdi-server', '', 'Defers CSS transitions until after the first browser paint to prevent flash-of-transition on SSR hydration. Returns an isBooted flag (false during SSR and the first rAF frame, then true) and a ssrBootStyles computed that injects `transition: none !important` while booting, suppressing unwanted entry animations during hydration.', NULL, 'function useSsrBoot(): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('382c82a5-87d6-405b-8f7f-b3d83d152f0b', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-stack', 'useStack', NULL, 'Commons', 'mdi-layers-outline', '', 'Manages z-index stacking order for overlay components (Dialog, Menu, Tooltip, Drawer, …). Registers the component in the global GLOBAL_STACK array when it becomes active and auto-computes a z-index 10 units above the current topmost overlay. Exposes globalTop (is this the topmost overlay worldwide?) and localTop (does this overlay have no active child overlays?) for pointer-event and close-on-outside-click decisions.', NULL, 'function useStack(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('d5ff8992-f6c8-40e3-8a11-9788bafc6249', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-state-effect', 'useStateEffect', NULL, 'Commons', 'mdi-palette-swatch-variant', '', 'Unified composable that consolidates eight visual axes (color, bgColor, border, rounded, elevation, padding, margin, gap) into a single state-aware layer. Reads the hover / active state and their override objects (IHoverState / IActiveState) and emits per-axis classes + styles for each axis. Replaces the prior chain of useColorEffect + useBorder + useRounded + useElevation + usePadding + useMargin that every visual component had to repeat.', NULL, 'function useStateEffect(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('146f56d7-33e9-4dcb-8487-9f27d2101300', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-state-flag', 'useStateFlag', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useStateFlag(props: object, options: IStateFlagOptions<S>): IStateFlagReturn', NULL, NULL, 'packages/ds/src/composables/Commons/stateFlag.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('94267cb7-4c81-4634-acd8-d9291bd43658', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-status', 'useStatus', NULL, 'Commons', 'mdi-alert-circle-outline', '', 'Resolves semantic status props (success, info, warning, error) into icon slots, status classes, and a forced intent color. The status intent overrides any color / bgColor the consumer passed — a status colour is non-negotiable by design. Also manages icon routing across prepend / append / replace slots based on statusIconPosition.', NULL, 'function useStatus(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('02bac23a-4f3f-4677-b6fb-07b08dd5f567', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-sticky', 'useSticky', NULL, 'Commons', 'mdi-pin-outline', '', 'Implements the "sticky-while-scrolling" pattern for taller-than-viewport navigation drawers. Tracks scroll direction and element bounding rect to decide whether the sidebar is stuck at the top, stuck at the bottom, or free-floating mid-page. Returns stickyStyles with the appropriate top/bottom offset so the sidebar scrolls naturally through long content without jumping.', NULL, 'function useSticky(options: ISticky): {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('68e22e53-cc5f-44ab-9586-3a1a01b1c39b', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'const', 'calendar-month-grid-weeks', 'CALENDAR_MONTH_GRID_WEEKS', 'Calendar', NULL, NULL, NULL, NULL, 'export const CALENDAR_MONTH_GRID_WEEKS = 6', NULL, NULL, '6', 'packages/ds/src/consts/Calendar/calendar.const.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
