INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('3a29f970-56ba-42ac-9487-ceb690629cc0', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-style', 'useStyle', NULL, 'Commons', 'mdi-code-tags', '', 'Injects a dynamic <style> tag into document.head scoped to a generated element id, allowing components to apply per-instance CSS that cannot be expressed as inline styles (e.g. pseudo-element rules, :hover selectors, @keyframes). Also exposes the lower-level useStyleTag for raw CSS string injection. Both composables manage their own lifecycle: they load on mount and unload on scope dispose.', NULL, 'function useStyle(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('a61ed005-3a76-41fc-9ea7-4bf76cb251bf', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-style-tag', 'useStyleTag', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useStyleTag(css: MaybeRef<string>, options?: IStyleTagOptions = {}): { id: string; css: Ref<string, string> | ShallowRef<string, string> | WritableComputedRef<string, string>; unload: () => void; load: () => void; isLoaded: Readonly<...>; }', NULL, NULL, 'packages/ds/src/composables/Commons/styleTag.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('abd5da22-66a7-476f-906b-5661381e868c', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-teleport', 'useTeleport', NULL, 'Commons', 'mdi-arrow-top-right-bold-box-outline', '', 'Resolves the Vue Teleport target for overlay components. Accepts true (disable teleport — render inline), false (teleport to document.body), a CSS selector string (teleport to the matched element), or a raw Element. Creates an .origam-overlay-container div inside the target when one does not already exist, so multiple overlays sharing the same target stack correctly without polluting the host''s direct children.', NULL, 'function useTeleport(
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('42507d13-cb39-46b3-b9a4-e9b3c4e2a1b9', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'composable', 'use-teleport-typography', 'useTeleportTypography', 'Commons', 'Commons', NULL, NULL, NULL, NULL, 'function useTeleportTypography(fieldRef: Ref<{ $el?: HTMLElement } | undefined>, isOpen: Ref<boolean>, extraVars: (fontSize: string) => Record<string, string>, measureSelector?: string = TELEPORT_TYPOGRAPHY_MEASURE_SELECTOR, neutralFontSize?: string = TELEPORT_TYPOGRAPHY_NEUTRAL_FONT_SIZE): { typographyStyles: Ref<Record<string, string>, Record<string, string>>; }', NULL, NULL, 'packages/ds/src/composables/Commons/teleport-typography.composable.ts', NULL, NULL, NULL, NULL, NULL, NULL, NULL, false, NULL, NULL, NULL, NULL, NULL, NULL);
