INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('0636d484-8028-4998-aaeb-a9468b40d7e7', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'interface', 'i-chart-sankey-props', 'IChartSankeyProps', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_props.description', 'Props for <OrigamChartSankey>. The component consumes series[0] only — each item in series[0].data must conform to IChartSankeyDatum ({ from, to, value }). Nodes are inferred automatically; columns are assigned by topological depth. Extends IChartBaseProps.', 'export interface IChartSankeyProps extends IChartBaseProps {
INSERT INTO public.doc_entry (id, created_at, updated_at, kind, slug, name, category, domain, icon, description_key, description_fallback, definition, signature, tag, value, source_file, package_note, note_key, note_fallback, story_url, doc_url, parent_slug, kind_extra, edited_by_user, editorial_locked_at, orphaned_at, svg_title_key, svg_title_fallback, svg_desc_key, svg_desc_fallback) VALUES ('4f7616cb-e561-42ad-9065-5405d3e22285', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'interface', 'i-chart-sankey-slots', 'IChartSankeySlots', 'Chart', NULL, NULL, 'interfaces.catalog.i_chart_sankey_slots.description', 'Slot signatures exposed by <OrigamChartSankey>. Extends IChartBaseSlots with a node-label slot that replaces the label rendered beside each node, receiving the node name, value, formatted value, resolved colour and column index.', 'export interface IChartSankeySlots extends IChartBaseSlots {
