INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9a978468-21ca-43c3-aeba-b220f4291111', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '25ed786e-414e-46ad-942f-77d997f4dc86', 'props', 'IActivatorProps', true, NULL, '', 'Props controlling how the overlay is triggered. Includes activator selector/element, open-on strategy (click, hover, focus, context-menu), close-on-content-click, delay settings inherited from IDelayProps, and an optional target override.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b7b04ef9-925b-41e7-bdd2-84b55ad089bb', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '25ed786e-414e-46ad-942f-77d997f4dc86', 'isActive', 'Ref<boolean>', true, NULL, '', 'Reactive flag representing the open/closed state of the overlay. useActivator reads and writes this ref to toggle the overlay on user interaction.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('48ebbb05-3d8a-4687-aaac-71faab053ab0', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '25ed786e-414e-46ad-942f-77d997f4dc86', 'isTop', 'Ref<boolean>', true, NULL, '', 'Reactive flag set by the overlay stack manager. When true, this overlay is the topmost one; when it becomes false while hover/focus-triggered, the composable auto-closes the overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('901284b0-8cfd-4668-8053-f39f8f13550d', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '99dd3ec4-8bb0-4f2c-92f4-45fdc65db51a', 'props', 'IActiveProps & Record<string, any>', true, NULL, '', 'Component props. Reads `props[prop]` (default: `props.active`).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6c8f6def-62e5-4b50-adf6-29b05397f592', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '99dd3ec4-8bb0-4f2c-92f4-45fdc65db51a', 'prop', 'string', false, '''active''', '', 'The prop key to read for the active value. Use "modelValue" for components with a v-model binding.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e577169a-b2c9-4ca7-8dbd-c39465557868', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '99dd3ec4-8bb0-4f2c-92f4-45fdc65db51a', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--active` class.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fe00a4f7-1dec-489d-a383-98550c90e3a7', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '5d3377e1-75da-4b61-aa47-03e49feee9a5', 'props', 'IAdjacentProps', true, NULL, '', 'Props carrying prependIcon, appendIcon, prependAvatar, and appendAvatar values. The composable reads these to determine whether the outer prepend/append regions should render.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f1c0c449-30c2-4cc6-848c-969b9782dd6a', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '5d3377e1-75da-4b61-aa47-03e49feee9a5', 'prependIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the prepend slot. When provided, takes precedence over props.prependIcon, enabling status-aware icon swapping without prop mutation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7e286e3d-ec53-4985-be23-eece9ce0ec1e', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '5d3377e1-75da-4b61-aa47-03e49feee9a5', 'appendIcon', 'Ref | ComputedRef', false, NULL, '', 'Optional reactive icon override for the append slot. Same semantics as prependIcon but for the trailing position.', 2, false, NULL, NULL);
