INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4ac5fdd4-e43f-4a95-a8f2-00e92fd1054b', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'a48bcb38-37c4-428e-b846-e2e64e2ff391', 'props', 'IUseAudioProps', true, NULL, '', 'Props object with audio (URL of the audio source) and playAudio (boolean flag). When playAudio changes to true the composable calls onPlay(); when it changes to false it calls onStop(). When audio changes, wasPlayed and isPlaying are reset.', 0, false, NULL, NULL);
