INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c49ed3f7-1f22-4bee-a96e-3e1a68bf1ffe', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'ea54b46f-025b-4d92-b5e0-47975c98e56d', 'props', 'ISizeProps', true, NULL, '', 'Component props extending ISizeProps. Reads the `size` value.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('874e9018-274f-4210-b929-47cf674beca1', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'ea54b46f-025b-4d92-b5e0-47975c98e56d', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the `{name}--size-{value}` class.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b1f254db-3839-49aa-93cc-0a04ab898d90', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '040b47ba-a8d1-431d-999b-ed4080751b40', 'props', 'ISliderFieldProps', true, NULL, '', 'Component props. Reads min (default 0), max (default 100), and step (default 0 = no stepping). All three accept string or number — they are parsed with parseFloat internally.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2c1b293b-22bc-49df-8b59-be6198dd53ca', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '0319b081-3ae7-4a52-b74d-d5797c7686ca', 'milliseconds', 'number', true, NULL, '', 'Total countdown duration in milliseconds. This is the initial value of time and the value it resets to on reset().', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7c254fa3-9fcc-4f06-98b3-40e02a7c71b5', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'e1063143-1660-44e8-a8ec-674c0d260948', 'options', 'IUseSnackbarGroupOptions', false, '{}', '', 'Optional configuration. id (string) namespaces the stack so multiple independent stacks can coexist on the same page (default: SNACKBAR_GROUP_DEFAULT_ID). max (number) caps the stack size with FIFO eviction. defaultDuration (ms) is the fallback auto-dismiss delay for items that omit their own (default: 5000 ms).', 0, false, NULL, NULL);
