INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('773ee2fc-023b-4cb1-a304-dc3f22019dc3', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '382c82a5-87d6-405b-8f7f-b3d83d152f0b', 'isActive', 'Readonly<Ref<boolean>>', true, NULL, '', 'Reactive open/closed state. When it flips to true, useStack registers the component in the global stack and computes a new z-index. When false, the entry is removed and z-index is released.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3f06f3bd-81dc-4c7d-8881-c0c45e949ecf', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '382c82a5-87d6-405b-8f7f-b3d83d152f0b', 'zIndex', 'Readonly<Ref<string | number>>', true, NULL, '', 'Base z-index to start from when no other overlays are open. Typically comes from the component props (e.g. zIndex="200").', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c7457915-4035-45d7-880e-b824d01433e5', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '382c82a5-87d6-405b-8f7f-b3d83d152f0b', 'disableGlobalStack', 'Readonly<Ref<boolean>>', true, NULL, '', 'When true, skips registration in GLOBAL_STACK. Use for overlays that manage their own z-index independently (e.g. nested teleport roots) and should not compete with the global stacking order.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8795cf3b-011c-47d5-b018-546f8cdc293a', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '1f42ae5a-7a5a-4239-aa6a-9781f9de0103', 'horizontal', 'boolean', false, NULL, '', '', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8e55b3c1-fbb2-4b3d-8c20-66ecff15676d', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'props', 'TStateEffectProps', true, NULL, '', 'Component props implementing all eight axes: IColorProps & IBgColorProps & IBorderProps & IRoundedProps & IElevationProps & IPaddingProps & IMarginProps & { gap? }. Also reads props.status when present to force the matching semantic intent (overrides color/bgColor).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('456d2f4b-8e7b-4597-bcd6-63682d5644dc', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'isHover', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive hover state from useHover. When true, the composable applies the override values from hoverState for each axis.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('45118e8d-16c3-4a53-a2bb-52a65a1c67d7', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'isActive', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'Reactive active/selected state from useActive. When true (and isHover is false), override values from activeState are applied. Hover takes priority when both are engaged simultaneously.', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('a4ab7fe8-7d6a-4632-9b20-6d35b8a77a36', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'hoverState', 'ComputedRef<IHoverState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useHover. Contains per-axis override values (color, bgColor, border, rounded, elevation, padding, margin, gap) to apply while hovered.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8113b972-49db-44d8-95da-83917e2d8153', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'activeState', 'ComputedRef<IActiveState | undefined>', false, 'computed(() => undefined)', '', 'State config object from useActive. Same shape as IHoverState — per-axis overrides applied while the item is selected/active.', 4, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0f5dad61-28df-4cce-9085-001530faec0e', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'isDisabled', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, colorClasses is emptied (utility classes suppressed) so the disabled opacity veil is not overridden by a tokenised background.', 5, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2ec074a3-6898-459a-8dd7-073973a5eb11', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'flat', 'Ref<boolean> | ComputedRef<boolean>', false, 'noopRef', '', 'When true, elevationClasses and elevationStyles resolve to empty. Bridges the flat prop of Btn / Card without requiring a separate useElevation call.', 6, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('262c19ca-30c3-4a77-8ff5-197325338238', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '146f56d7-33e9-4dcb-8487-9f27d2101300', 'props', 'object', true, NULL, NULL, NULL, 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cc8e3a88-f73d-4739-9a94-53951c55580c', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '146f56d7-33e9-4dcb-8487-9f27d2101300', 'options', 'IStateFlagOptions<S>', true, NULL, NULL, NULL, 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8d707e7f-a878-4ec4-9fca-4bdcab755302', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '94267cb7-4c81-4634-acd8-d9291bd43658', 'props', 'IStatusProps & IAdjacentProps', true, NULL, '', 'Component props. Reads status (TStatus: success | info | warning | error), statusIconPosition (prepend | append | both | replace), prependIcon, appendIcon, and icon. When status is set and statusIconPosition is replace, the status icon overwrites props.icon; when prepend/append/both, it fills the matching slot only if no explicit icon prop was passed.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5bd17b13-cf66-478a-934a-50104405f228', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '94267cb7-4c81-4634-acd8-d9291bd43658', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name used to build the BEM modifier class `{name}--{status}` (e.g. origam-alert--success). Defaults to the current Vue instance name.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('02bd77cb-b25c-40a9-b618-606117538e51', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '02bac23a-4f3f-4677-b6fb-07b08dd5f567', 'rootEl', 'Ref<HTMLElement | undefined>', true, NULL, NULL, NULL, 0, false, NULL, NULL);
