INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7bd13e09-bf7e-4228-a244-2b5e0a586707', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3a29f970-56ba-42ac-9487-ceb690629cc0', 'styles', 'ComputedRef', true, NULL, '', 'A ComputedRef returning a CSS value array or object. Accepts the same formats as Vue :style bindings (array of objects, strings, or mixed). useStyle normalises this to a flat `#id { prop: value; … }` string and feeds it to useStyleTag.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d30877dc-97e3-499d-a431-0d8dc6dfc75d', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3a29f970-56ba-42ac-9487-ceb690629cc0', 'uniq', 'MaybeRefOrGetter<string | undefined>', false, 'undefined', '', 'Optional fixed element id. When omitted, a unique id is generated from the component name and a counter (e.g. origam-card-3). Provide a fixed id when multiple instances must share the same <style> tag (e.g. global animation keyframes).', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4858c538-377e-4a43-b4e1-a4d96ddf0c25', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3a29f970-56ba-42ac-9487-ceb690629cc0', 'name', 'string', false, 'getCurrentInstanceName()', '', 'Component name prefix for the generated id. Defaults to the current Vue instance name.', 2, false, NULL, NULL);
