INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ee3f0a64-47da-427f-8c1d-7479f82feb3b', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '14cfe730-9496-4251-9de8-81beb38ce377', 'options', 'IUseTextareaRichOptions', true, NULL, '', 'Configuration object. value: () => string — getter for the initial HTML content (bound to the parent v-model). onUpdate: (html: string) => void — called with sanitised HTML on every change. onFormat: (command, value?) => void — called after each format command (lets the host open a link popover on Cmd+K). disabled: () => boolean — suppresses all commands and keyboard shortcuts when true.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fb815c1b-dcd0-43f5-8aab-b0287b397fd4', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'be420402-92af-4352-b6ed-24b4d18a6ff6', 'props', 'T | Ref<TColor>', true, NULL, '', 'Either the component props object (paired with `name`) or a plain Ref<TColor>.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5aecdee9-1b06-4d0f-b9dd-7f8b227dde32', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'be420402-92af-4352-b6ed-24b4d18a6ff6', 'name', 'K', false, NULL, '', 'The key to read from the props object. Typically "color". Omit when passing a plain Ref.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ab1caf17-a995-4d50-aa05-350d63f19a28', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '149b6a0c-3428-46c8-8b0b-8423d4652952', 'fn', '(...args: T) => R', true, NULL, '', 'The function to throttle. Called immediately on the first invocation within each window. The return value is discarded — the wrapper always returns void.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e5038938-a36f-430d-ac0a-ab2e8713f12f', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '149b6a0c-3428-46c8-8b0b-8423d4652952', 'wait', 'number', true, NULL, '', 'Throttle window in milliseconds. No call will execute within wait ms of the previous execution.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('44da54d5-a2ed-483a-9d08-b66c9ba798a1', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '39814d67-a21c-4349-a172-6f7d1b95fd86', 'source', 'WatchSource<boolean>', true, NULL, '', 'Reactive boolean source (ref, computed, or getter). When it evaluates to true the scope is started; when false the scope is stopped.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ad1c6c93-de61-4c6d-9c14-7e39b9efaf09', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '39814d67-a21c-4349-a172-6f7d1b95fd86', 'fn', '(reset: () => void) => void', true, NULL, '', 'Callback run inside the new effectScope. Receives a `reset()` function that can be called from inside the scope to stop the current scope and immediately restart it — useful for subscriptions that need to re-initialise when an inner condition changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ae4c2b99-7c7e-4b7b-ab3b-c008622cb016', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'ed009c80-0c8b-428c-88d5-e0eb9e85dda0', 'isTemporary', 'Ref<boolean>', true, NULL, '', 'When true the drawer is temporary (modal overlay). The touch zone logic also activates for touches anywhere inside the element body, not only at the edge.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5802f373-6628-4333-b1da-c45008a8c66f', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'ed009c80-0c8b-428c-88d5-e0eb9e85dda0', 'width', 'Ref<number>', true, NULL, '', 'Pixel width (or height for top/bottom positions) of the drawer. Used to compute drag progress as a fraction in [0, 1].', 2, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fe589f7c-77d6-4aaf-9e6f-cf8c41c78c30', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'ed009c80-0c8b-428c-88d5-e0eb9e85dda0', 'touchless', 'Ref<boolean>', true, NULL, '', 'When true all touch handling is disabled. Lets the consumer disable swipe gestures without unmounting the composable.', 3, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d041b45d-c972-43f1-9468-73bb7507b3ce', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'ed009c80-0c8b-428c-88d5-e0eb9e85dda0', 'position', 'Ref<''left'' | ''right'' | ''top'' | ''bottom''>', true, NULL, '', 'The edge from which the drawer slides in. Determines the touch zone, coordinate axis, and transform direction.', 4, false, NULL, NULL);
