INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('99441a72-f700-4297-a827-5dbfa343f207', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'a0bab201-537a-497b-a9bf-bab3ee0f0a5b', 'name', 'string', false, 'getCurrentInstanceName()', '', 'The BEM block prefix. Defaults to the current component name (e.g. `origam-btn`). The class produced will be `{name}--variant-{variant}`.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9110cf5a-3c31-41c1-855f-ffdb3cfd4fc4', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'b3dbe520-484f-4ed8-a27c-b811cc5d51e0', 'options', 'IUseVideoPlayerOptions', false, '{}', '', 'Accepts `videoRef` (bring your own typed ref), `autoplay`, `muted`, `loop`, `preload`. All optional. Autoplay is suppressed when prefers-reduced-motion is active.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2b1d3c0c-9eaf-4e58-8cae-ab07017bbd1e', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3e26a7bd-18f5-41bf-af04-01569d11b3c5', 'props', 'IVirtualProps', true, NULL, '', 'Reads `itemHeight` (expected row height in px, used to estimate the initial window), `height` (container height as string / number), `scrollDuration` (ms, default 300), `scrollEasing` (easing name, default easeInOutCubic).', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('124451a1-f00e-4588-b010-c45e9d25c858', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3e26a7bd-18f5-41bf-af04-01569d11b3c5', 'items', 'Ref<readonly T[]>', true, NULL, '', 'The full dataset ref. The composable slices this array to produce `computedItems`. Changing the ref triggers an offset recalculation.', 1, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('65dc52e0-0009-4c2b-9015-8047b01f4d8a', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '9ac6f6d7-4ade-483a-ab56-760faf0c086f', 'props', 'Props', true, NULL, '', 'The component props object returned by defineProps. The composable reads `props[prop]` and inspects `vm.vnode.props` to detect whether the listener is wired.', 0, false, NULL, NULL);
INSERT INTO public.doc_param (id, created_at, updated_at, entry_id, name, type, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('29f6ca66-e6c2-4b52-bb53-3235330e5d40', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '9ac6f6d7-4ade-483a-ab56-760faf0c086f', 'prop', 'Prop', true, NULL, '', 'The prop key to observe, e.g. `"modelValue"` for a standard v-model binding.', 1, false, NULL, NULL);
