INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4c6e3eaf-bd36-4b58-8764-5036be57dada', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', 'ac604433-4127-49cf-b7f9-57d4058fcbaa', 'lang', 'TCodeLangOpen', 'code-lang', 'type', NULL, false, '''plaintext''', 'components.code.props.lang.description', 'Language grammar to apply. Supported: ''plaintext'' | ''vue'' | ''ts'' | ''js'' | ''tsx'' | ''jsx'' | ''scss'' | ''css'' | ''json'' | ''bash'' | ''html'' | ''xml'' | ''yaml'' | ''md''. Unknown values fall back to plaintext.', 1, false, NULL, NULL);
