INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c1c82ab1-cc55-45f4-a103-35a05f55c114', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', 'ac604433-4127-49cf-b7f9-57d4058fcbaa', 'copyable', 'boolean', '', 'primitive', NULL, false, 'true', 'components.code.props.copyable.description', 'Shows the copy-to-clipboard button. True by default — most code blocks benefit from it.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cda4d3ad-8958-41eb-b076-a02bbe8f1127', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', 'ac604433-4127-49cf-b7f9-57d4058fcbaa', 'format', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.format.description', 'Auto-format the code before highlighting. Reserved — currently a no-op that warns in dev mode. Prettier is not bundled at runtime to keep the tarball small.', 5, false, NULL, NULL);
