INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d4b58a44-b236-4032-8ee9-821ecfd42de5', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', 'ac604433-4127-49cf-b7f9-57d4058fcbaa', 'compact', 'boolean', '', 'primitive', NULL, false, 'false', 'components.code.props.compact.description', 'Renders as a single-line inline pill (ideal for install commands). Header, filename and line numbers are suppressed; the copy button collapses to a small icon.', 8, false, NULL, NULL);
