INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2e2920e2-0b73-47e9-9253-50f03a64f1c3', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'state', 'IMediaPlayerState', '', 'primitive', NULL, true, '—', 'components.media_controller.props.state.description', 'Reactive media state from useMediaPlayer() (or a specialisation: useVideoPlayer, useAudioPlayer). Contains refs for playing, currentTime, duration, volume, muted, buffered, playbackRate, remoteAvailable, remoteState.', 0, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f1cb03af-2b93-4dcc-bbbe-21375c4e7c5d', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'methods', 'IMediaPlayerMethods', '', 'primitive', NULL, true, '—', 'components.media_controller.props.methods.description', 'Imperative methods from useMediaPlayer(). Provides play(), pause(), seek(), setVolume(), toggleMute(), setPlaybackRate(), requestRemotePlayback().', 1, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e4d47911-419b-4d79-b69e-acbb58bf2ed3', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'inset', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.inset.description', 'YouTube-style overlay mode: the shell sits on top of the media surface with a dark gradient and auto-hides on visible=false. When false, renders as a regular always-on toolbar.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('49353e26-64a4-45b3-b3fe-0e64ec1663dc', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'visible', 'boolean', '', 'primitive', NULL, false, 'true', 'components.media_controller.props.visible.description', 'Visibility flag driven by the parent autohide logic. Only meaningful when inset=true. When false, the shell is opacity: 0 and pointer-events: none.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e04bfa0e-fb49-4771-a94b-aaa78c96ec47', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'playbackRates', 'ReadonlyArray<number>', '', 'primitive', NULL, false, '[0.5, 0.75, 1, 1.25, 1.5, 2]', 'components.media_controller.props.playback_rates.description', 'Available playback rates exposed via the config cog menu. When the array has more than 1 entry, a "Playback speed" drill-down appears.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f986a88c-3729-4906-a60f-f035613661f6', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'allowRemotePlayback', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.allow_remote_playback.description', 'Enable the Cast / AirPlay button (Remote Playback API). The button only appears when this flag is true AND state.remoteAvailable is true at runtime.', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('112a8042-bcaa-475e-9921-16a7c4e8fd89', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'downloadable', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.downloadable.description', 'Adds a "Download" row to the config cog menu when true. Requires downloadUrl to be set.', 6, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9cd9eb5a-e97e-4ea1-85f8-6c8a76c5acb5', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'downloadUrl', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.download_url.description', 'URL surfaced to the consumer when the Download menu item is clicked. Supports same-origin, data: and blob: URLs natively; cross-origin URLs are routed through a fetch → blob pipeline.', 7, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('40bb041b-17f7-4793-abd1-1efb01c5b2e2', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'downloadFilename', 'string', '', 'primitive', NULL, false, 'undefined', 'components.media_controller.props.download_filename.description', 'Suggested filename for the downloaded file (<a download="…"> attribute).', 8, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('238cd4ec-0939-47ed-8f42-44086dfbe27f', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'qualityOptions', 'ReadonlyArray<TQualityOption>', '', 'primitive', NULL, false, '[]', 'components.media_controller.props.quality_options.description', 'Optional list of quality variants. When ≥ 2 entries are present, a "Quality" drill-down appears in the config menu. Each entry is { quality: string; label: string }.', 9, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d502a5bb-af6f-470f-81e0-b03f1c3dfe3c', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'currentQuality', 'string | null', '', 'primitive', NULL, false, 'null', 'components.media_controller.props.current_quality.description', 'Currently-active quality identifier displayed as the appendText in the Quality menu row.', 10, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0f8ed34b-c30c-4a1f-b8f0-7a0872e8df4b', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'showPrevious', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_previous.description', 'Show the "previous track" transport button. The parent listens to the previous emit and decides the action (skip back 10s or jump to the previous playlist track).', 11, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e97e6a0c-8d48-4353-af11-6fbb88664655', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'showNext', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_next.description', 'Show the "next track" transport button. The parent owns the action.', 12, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dd23877f-b4e6-4a45-ad17-69ed21d811b8', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '8a32fb93-b22b-420f-bff1-ea41e76e3da4', 'showLoop', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_controller.props.show_loop.description', 'Show the tri-state loop button (none → all → one → none). Supports v-model:loopMode.', 13, false, NULL, NULL);
