INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d7adffa2-bce4-4279-8537-5b2840653a2a', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '2754fcce-bf61-4568-9002-e3a022775821', 'modelValue', 'number', '', 'primitive', NULL, true, '—', 'components.media_scrubber.props.model_value.description', 'Current value between min and max. Supports v-model. The component never mutates this directly — every change surfaces via update:modelValue.', 0, false, NULL, NULL);
