INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0119cb7f-af96-4649-9b0a-8a3caa97d948', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '2754fcce-bf61-4568-9002-e3a022775821', 'max', 'number', '', 'primitive', NULL, true, '—', 'components.media_scrubber.props.max.description', 'Upper bound of the value range. Required to compute the thumb position. Passing 0 or any value <= min freezes the scrubber at the start.', 2, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dc135082-f091-4e3a-922f-6256f1151a0b', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '2754fcce-bf61-4568-9002-e3a022775821', 'step', 'number', '', 'primitive', NULL, false, '0', 'components.media_scrubber.props.step.description', 'Discrete step. 0 (default) means continuous — pointer events emit the raw float; positive values snap each emission to the nearest multiple.', 3, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fd81b19d-e23d-443d-87ce-fb0bf14cd599', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '2754fcce-bf61-4568-9002-e3a022775821', 'buffered', 'number', '', 'primitive', NULL, false, 'undefined', 'components.media_scrubber.props.buffered.description', 'Optional buffered position (end of the browser''s media buffer). Renders the __buffer bar from min up to buffered. Pass undefined to hide the bar entirely.', 4, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d2a8e0fa-2b13-457b-aed1-e68be7a0a82e', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '2754fcce-bf61-4568-9002-e3a022775821', 'orientation', 'TMediaScrubberOrientation', '', 'primitive', NULL, false, '''horizontal''', 'components.media_scrubber.props.orientation.description', 'Layout axis. horizontal = YouTube timeline shape; vertical = volume / level meter shape (top of track = max, bottom = min).', 5, false, NULL, NULL);
INSERT INTO public.doc_prop (id, created_at, updated_at, entry_id, name, type_label, type_slug, type_kind, optional, required, default_value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('321f6b5b-d18b-4a9b-bf29-50fac95b27d8', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:24.901372+00', '2754fcce-bf61-4568-9002-e3a022775821', 'disabled', 'boolean', '', 'primitive', NULL, false, 'false', 'components.media_scrubber.props.disabled.description', 'Disables pointer + keyboard interaction. The element drops out of the tab order (tabindex="-1") and pointer events become no-ops.', 6, false, NULL, NULL);
