INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8f11beed-a4c6-4008-9970-9efe531b4321', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '040b47ba-a8d1-431d-999b-ed4080751b40', 'step', 'ComputedRef<number>', '', 'Parsed step value. 0 means no stepping (any value between min and max is valid). Positive values define the snap grid.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d1cdd5e4-b7ed-4042-8f72-a5797bd3b762', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '040b47ba-a8d1-431d-999b-ed4080751b40', 'decimals', 'ComputedRef<number>', '', 'Number of decimal places to preserve in roundValue output. Derived from max(getDecimals(step), getDecimals(min)) to match the precision implied by the step grid.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0d2a2fca-941e-49b0-afcb-e4368e0469cd', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '040b47ba-a8d1-431d-999b-ed4080751b40', 'roundValue', '(value: string | number) => number', '', 'Snap a raw value to the nearest valid step, clamped to [min, max]. Handles the min-offset edge case so that a step=5 min=3 grid snaps to 3, 8, 13, … rather than 0, 5, 10, ….', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('87f2d1e9-6eaa-4867-aa07-464b950f0096', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '0319b081-3ae7-4a52-b74d-d5797c7686ca', 'time', 'ShallowRef<number>', '', 'Remaining milliseconds. Starts at the initial milliseconds value, decrements on each tick, and bottoms out at 0. Bind to a progress bar width to visualise the countdown.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d4ec0408-a008-47a0-935f-f8c9c1d48478', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '0319b081-3ae7-4a52-b74d-d5797c7686ca', 'clear', '() => void', '', 'Stops the interval without resetting time. Use to pause the countdown (e.g. while the user is hovering the snackbar).', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9a58057d-a87a-4bdb-8661-58a5d13273c1', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '0319b081-3ae7-4a52-b74d-d5797c7686ca', 'reset', '() => void', '', 'Clears the interval and resets time to the initial milliseconds value on the next tick. Use when the snackbar content changes and the countdown should restart.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1da2d758-a70d-4866-a5a4-4f9ed7d50c43', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '0319b081-3ae7-4a52-b74d-d5797c7686ca', 'start', '(el?: HTMLElement) => void', '', 'Start (or resume) the countdown. Reads the CSS transitionDuration of el to synchronise tick frequency with the progress bar animation. Falls back to 200 ms when no element is provided or no transition is set. Clears any existing interval before starting.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2d4dd15e-f491-4ba6-94fe-f1599d94e568', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'e1063143-1660-44e8-a8ec-674c0d260948', 'items', 'Readonly<Ref<ReadonlyArray<ISnackbarGroupItem>>>', '', 'Reactive read-only snapshot of the current stack. Mutate only through notify / dismiss / dismissAll — direct writes are blocked at the TypeScript level.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('06a30f25-b930-42ea-b5e8-fbf6b8b768d5', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'e1063143-1660-44e8-a8ec-674c0d260948', 'notify', '(opts: ISnackbarGroupItemOptions) => string', '', 'Push a new item onto the stack. Accepts ISnackbarGroupItemOptions (message, variant, icon, duration, onDismiss callback…). Returns the generated item id so the caller can dismiss it early.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('25af1352-690b-486c-ba7f-2919207fc3a5', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'e1063143-1660-44e8-a8ec-674c0d260948', 'dismiss', '(itemId: string) => void', '', 'Remove the item with the given id from the stack, cancel its auto-dismiss timer, and invoke its onDismiss callback if any.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('807a7a89-9ea8-4e1f-8069-8760775823b4', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'e1063143-1660-44e8-a8ec-674c0d260948', 'dismissAll', '() => void', '', 'Dismiss every item in the stack in one call. Iterates a snapshot of the ids so mid-loop mutations are safe.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('fc09f963-4087-42f1-8f2c-d1f41fb233bb', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '51d5f35e-393a-41d1-9abe-4989f044292d', 'sortBy', 'Ref<Array<IDataTableSortItem>>', '', 'Reactive array of active sort descriptors, each with a key (column key) and an order (asc | desc). Driven by useVModel against the host table props.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3ae0d729-5770-4ded-8304-251d0bb4c607', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '51d5f35e-393a-41d1-9abe-4989f044292d', 'toggleSort', '(column: IInternalDataTableHeader) => void', '', 'Cycle the sort state for a column: none → asc → desc → none (or asc when mustSort=true). Respects multiSort — when false, replaces the entire sortBy array with a single entry.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('85d5950d-39b4-4a17-9584-038721591210', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '51d5f35e-393a-41d1-9abe-4989f044292d', 'isSorted', '(column: IInternalDataTableHeader) => boolean', '', 'Returns true when the column has an active sort entry in sortBy. Used by header cells to show the sort icon.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2f3d567f-e209-47d3-9057-14e6f1e2279f', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '6f88f7e1-33c3-46bf-838e-dd34ee42a30b', 'ssrBootStyles', 'ComputedRef<CSSProperties | []>', '', 'An object `{ transition: "none !important" }` when the component has not yet booted, or an empty array after the first animation frame. Spread onto the root element via :style to suppress hydration-flash transitions.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('01da998a-7bf7-4641-adae-a9fe27a417b5', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '6f88f7e1-33c3-46bf-838e-dd34ee42a30b', 'isBooted', 'Readonly<ShallowRef<boolean>>', '', 'False on the server and during the first rAF after mount, true thereafter. Useful as a guard before running DOM-dependent logic that assumes the component is fully hydrated.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4ba48351-16fc-4a60-b0f0-79f8bd9b3a86', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3965b478-5fbe-4cac-a809-29f97c3ce661', NULL, 'number', 'utils.detail.apc_acontrast.returns', 'Signed APCA contrast value. Absolute value >= 45 is the recommended minimum for body text.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('c44d0153-5e05-4c77-846b-10df348a68c7', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '382c82a5-87d6-405b-8f7f-b3d83d152f0b', 'globalTop', 'Readonly<ShallowRef<boolean>>', '', 'True when this component is the last entry in GLOBAL_STACK (topmost overlay on the page). Updated asynchronously via setTimeout to avoid synchronous circular reads during stack registration.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5942d3b2-10e6-4682-9f1c-edec383e6e92', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '382c82a5-87d6-405b-8f7f-b3d83d152f0b', 'localTop', 'ComputedRef<boolean>', '', 'True when this overlay has no active child overlays (nothing opened on top of it within its own sub-tree). Used to decide whether clicks on the backdrop should close this overlay.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e9feaa38-cb25-4974-948e-7d9a254006ec', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '382c82a5-87d6-405b-8f7f-b3d83d152f0b', 'stackStyles', 'ComputedRef<{ zIndex: number }>', '', 'Style object containing the computed zIndex. Spread onto the overlay root element so it automatically rises above the previous topmost overlay.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dc0dd02f-e5a8-4369-962b-5993c40dc30c', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'colorClasses / colorStyles', 'ComputedRef<string[]>', '', 'Tokenised intent values emit a utility class (origam--bg-primary); custom CSS colors emit an inline style. Both are empty when disabled/hover/active is true (state-inline path takes over).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('5da3dc93-4a79-4fb6-b78e-c256811b147a', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'borderClasses / borderStyles', 'ComputedRef<string[]>', '', 'Delegated to useBorder with a reactive proxy that swaps to hoverState/activeState.border when the state is engaged.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('cd7714d1-2bec-4219-b1ea-ca17a034f95e', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'roundedClasses / roundedStyles', 'ComputedRef<string[]>', '', 'Delegated to useRounded. State-aware: applies hoverState/activeState.rounded when engaged.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e742b787-043b-4877-aa09-400aaf48237b', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'elevationClasses / elevationStyles', 'ComputedRef<string[]>', '', 'Delegated to useElevation. Cleared when flat=true. State-aware via the pickEffective resolver.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('27115800-c50a-4425-8b19-b3474d148700', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'paddingClasses / paddingStyles', 'ComputedRef<string[]>', '', 'Delegated to usePadding via a reactive getter proxy to preserve dependency tracking across state swaps.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('473393b4-8bcc-471b-bd7a-3537ce35fc80', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'marginClasses / marginStyles', 'ComputedRef<string[]>', '', 'Delegated to useMargin via a reactive getter proxy.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7806dd1a-5c04-4bb8-a605-9826dd062a26', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'd5ff8992-f6c8-40e3-8a11-9788bafc6249', 'gapClasses / gapStyles', 'ComputedRef<string[]>', '', 'Gap has no dedicated composable. Emits an inline style (gap: Npx or gap: <value>) when a gap override is present. gapClasses is always empty.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('537b9197-8a2e-473a-931f-2f528c9bf2ae', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '94267cb7-4c81-4634-acd8-d9291bd43658', 'icon', 'ComputedRef<string | undefined>', '', 'Resolved center/replace icon. Returns the status icon when statusIconPosition="replace" and no explicit props.icon was provided, otherwise passes through props.icon.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('459b8d36-9fc9-41b4-b85c-d75c6cd55280', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '94267cb7-4c81-4634-acd8-d9291bd43658', 'prependIcon', 'ComputedRef<string | undefined>', '', 'Resolved prepend-slot icon. Injects the status icon when statusIconPosition is prepend or both and props.prependIcon is unset.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('91983285-5ec9-4655-8173-aace05096e83', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '94267cb7-4c81-4634-acd8-d9291bd43658', 'appendIcon', 'ComputedRef<string | undefined>', '', 'Resolved append-slot icon. Injects the status icon when statusIconPosition is append or both and props.appendIcon is unset.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('3f8287a8-7268-46b8-95cd-dff7c3f13b16', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '94267cb7-4c81-4634-acd8-d9291bd43658', 'statusClasses', 'ComputedRef<string[]>', '', 'Array containing `{name}--{status}` when a status is set, empty otherwise. Bind to the root element for SCSS state selectors.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('622ea8ed-57e5-4a6d-afda-62c025c322bb', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '94267cb7-4c81-4634-acd8-d9291bd43658', 'statusIntent', 'ComputedRef<TColor | undefined>', '', 'The resolved TColor intent for the current status (success→success, info→info, warning→warning, error→danger). Undefined when no status is set. Consumed by useStateEffect to force the semantic surface color.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2772e6ed-804c-4824-a8cd-c0bff7111b7b', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '02bac23a-4f3f-4677-b6fb-07b08dd5f567', 'isStuck', 'ShallowRef<boolean | "top" | "bottom">', '', 'Current stuck state. "top" = anchored at the top of the viewport (sidebar shorter than viewport or scrolled to top), "bottom" = anchored at the bottom edge, true = stuck mid-page (sidebar taller than viewport, user scrolled past the top edge), false = not sticky (isSticky prop is false).', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('0ffc47d6-9f84-46fd-b69e-31cbb1300f37', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '02bac23a-4f3f-4677-b6fb-07b08dd5f567', 'stickyStyles', 'ComputedRef<Array<CSSProperties | undefined>>', '', 'Two-element style array to spread on the element. The first resets top/bottom/height when isSticky is enabled. The second applies the computed positional offset: the layoutItem top when not yet stuck, or the scrolled stuckPosition when stuck mid-page or at the bottom.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('92c434df-ce22-49c8-a3b8-7b1bceec5dc9', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3a29f970-56ba-42ac-9487-ceb690629cc0', 'id', 'ComputedRef<string>', '', 'The element id used as the CSS scope selector (#id). Apply this id to the root element of the component so the injected styles target only this instance.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('8104674f-9482-4396-a477-2c47dd86d6b4', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3a29f970-56ba-42ac-9487-ceb690629cc0', 'css', 'ShallowRef<string>', '', 'The current generated CSS string. Reactive — updates whenever the styles ComputedRef changes.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f7ff9f49-977a-41aa-a5d5-da806661d039', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3a29f970-56ba-42ac-9487-ceb690629cc0', 'load / unload', '() => void', '', 'Manually control style tag injection. Normally called automatically on mount / scope dispose. Call load() to re-inject after an explicit unload().', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9def6c0d-16d0-41f0-8a35-fbe12f1edde5', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3a29f970-56ba-42ac-9487-ceb690629cc0', 'isLoaded', 'Readonly<ShallowRef<boolean>>', '', 'True when the <style> tag is currently present in document.head.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('7af23ca3-78dc-46c6-8de9-0c6b31293e5f', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'abd5da22-66a7-476f-906b-5661381e868c', 'teleportTarget', 'ComputedRef<Element | undefined>', '', 'The resolved .origam-overlay-container element inside the target, or undefined when teleport is disabled (target=true) or the app is running on the server (SSR). Pass directly to <Teleport :to="teleportTarget">.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('17261cdd-e6b0-4d7a-adcb-fa58a2f83676', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '14cfe730-9496-4251-9de8-81beb38ce377', 'hostRef', 'Ref<HTMLElement | undefined>', '', 'Template ref to assign to the contenteditable element. The composable uses it to read and write innerHTML, attach the selectionchange listener, and focus the element before applying a format command.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ece4ff1b-8dc9-4753-ad26-f4680196842d', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '14cfe730-9496-4251-9de8-81beb38ce377', 'active', 'ITextareaRichActiveState', '', 'Reactive object tracking the formatting state at the current caret position. Properties: bold, italic, underline, code, link (booleans), listBullet, listOrdered (booleans), heading (0 | 1 | 2 | 3). Bind to toolbar button :active props.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('dece8aae-ddf3-4c4d-90cb-96a59af6cfb3', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '14cfe730-9496-4251-9de8-81beb38ce377', 'format', '(command: TTextareaToolbarCommand, value?: string) => void', '', 'Apply a formatting command. Delegates to document.execCommand for bold, italic, underline, lists, and headings. Handles link creation (value = URL) and inline code toggling (insertHTML). Calls onFormat and onUpdate after every change.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('4ea7aa47-b977-4ca2-ac8d-eb6791cb6ec6', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '14cfe730-9496-4251-9de8-81beb38ce377', 'isFormatActive', '(command: TTextareaToolbarCommand) => boolean', '', 'Returns whether the given command is active at the current caret position. Reads from the reactive active object — a convenience wrapper for toolbar binding.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f837bffd-69ca-4d42-bc6c-e39ec20a766b', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '14cfe730-9496-4251-9de8-81beb38ce377', 'setValue', '(html: string) => void', '', 'Imperatively update the contenteditable innerHTML with sanitised HTML. No-ops when hostRef is unset or when the content is already identical (avoids cursor jump).', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d324ea53-970c-4d9d-9543-1bb3d7794e69', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '14cfe730-9496-4251-9de8-81beb38ce377', 'onInput / onKeydown / onPaste', '(event) => void', '', 'Event handlers to bind on the host element. onInput emits sanitised HTML. onKeydown intercepts Cmd/Ctrl+B/I/U/E/K and Cmd+Shift+7/8 for list shortcuts. onPaste strips HTML to sanitised form (or escapes plain text) before inserting.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b0fc3771-f222-4a45-b9ec-07c641edf5ed', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'be420402-92af-4352-b6ed-24b4d18a6ff6', 'textColorClasses', 'ComputedRef<string[]>', '', 'Utility class names (e.g. ["origam--color-primary"]) to bind via :class.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b042ff57-186e-47b2-ab11-648d8273960c', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'be420402-92af-4352-b6ed-24b4d18a6ff6', 'textColorStyles', 'ComputedRef<string[]>', '', 'Inline CSS declarations (e.g. ["color: #6d28d9"]) to bind via :style. For gradients, includes background-image + background-clip: text.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e831446e-bea3-4cca-ac32-8e1fb0c874a2', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'c9a90cb6-e42c-4593-abcd-aeef75db6745', 'theme', 'Readonly<Ref<TTheme>>', '', 'The current brand theme value: ''auto'' | ''light'' | ''dark'' | string (custom brand). Read-only reactive ref.', 0, false, NULL, NULL);
