INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('010bceba-1cb4-4419-8ac6-cbf48779e480', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'b3dbe520-484f-4ed8-a27c-b811cc5d51e0', 'videoRef', 'Ref<HTMLVideoElement | null>', '', 'Template ref to bind to the `<video>` element. Reused from `options.videoRef` when provided.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('008a12e6-4d31-4d97-a7ed-e4803cbd3941', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'b3dbe520-484f-4ed8-a27c-b811cc5d51e0', 'state', 'IVideoPlayerState', '', 'All IMediaPlayerState fields (playing, paused, currentTime, duration, buffered, volume, muted, ready, loading, error, playbackRate, remoteAvailable, remoteState) plus `fullscreen: Ref<boolean>` and `pip: Ref<boolean>`.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('2a88cd93-270e-4cde-9d0d-c35f2abf4c0a', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'b3dbe520-484f-4ed8-a27c-b811cc5d51e0', 'methods', 'IVideoPlayerMethods', '', 'All IMediaPlayerMethods (play, pause, toggle, seek, setVolume, toggleMute, load, skipBackward, skipForward, setPlaybackRate, requestRemotePlayback, stopRemotePlayback) plus `enterFullscreen`, `exitFullscreen`, `toggleFullscreen`, `requestPip`, `exitPip`, `togglePip`.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('b18b0b22-def6-4773-b5bb-f824be0555db', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3e26a7bd-18f5-41bf-af04-01569d11b3c5', 'containerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to the scrollable container element. The composable reads `scrollTop` from it and listens to `handleScroll` / `handleScrollend`.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ce08994a-77aa-4d96-9e1d-70e6aec95d61', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3e26a7bd-18f5-41bf-af04-01569d11b3c5', 'markerRef', 'Ref<HTMLElement | undefined>', '', 'Assign to a zero-height element at the top of the list content area. Its `offsetTop` is used to compute an offset if there is padding or a header above the virtual list.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('ae9f1c74-9f2d-4d94-9f2c-9369e9b4439a', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3e26a7bd-18f5-41bf-af04-01569d11b3c5', 'computedItems', 'ComputedRef<Array<{ raw: T; index: number }>>', '', 'The slice of items currently in the render window. Each entry carries the original `raw` item and its absolute `index` in the full list.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('bd9e5d50-13cc-4b2a-8f6e-8f01c8ee5955', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3e26a7bd-18f5-41bf-af04-01569d11b3c5', 'paddingTop', 'ShallowRef<number>', '', 'Pixel padding to add above the first rendered item to preserve the scroll height.', 3, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('81c164a5-654f-4d14-87ea-f5882fdab95d', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3e26a7bd-18f5-41bf-af04-01569d11b3c5', 'paddingBottom', 'ShallowRef<number>', '', 'Pixel padding to add below the last rendered item to preserve the scroll height.', 4, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('9a7b3e7d-ba3c-419f-8d33-092833fd7536', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3e26a7bd-18f5-41bf-af04-01569d11b3c5', 'scrollToIndex', '(index: number, options?: Partial<IGoToOptions>) => void', '', 'Programmatically scroll the container to a specific item index. Defers the scroll if the list has not yet measured (first render not complete). Pass `{ duration: 0 }` for instant scroll.', 5, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('d7a01c65-5d4e-4c51-bb5b-0af70ef39107', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3e26a7bd-18f5-41bf-af04-01569d11b3c5', 'handleScroll', '() => void', '', 'Bind to the `scroll` event of the container element. Computes scroll velocity and triggers visible-items recalculation.', 6, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1a98cb14-c018-4a06-bf1a-1c4fae2600a5', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3e26a7bd-18f5-41bf-af04-01569d11b3c5', 'handleScrollend', '() => void', '', 'Bind to the `scrollend` event. Resets scroll velocity and recalculates the visible window.', 7, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('508bfda9-536f-4fcd-9379-db498bece112', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3e26a7bd-18f5-41bf-af04-01569d11b3c5', 'handleItemResize', '(index: number, height: number) => void', '', 'Call when a rendered item changes its measured height. Updates the size cache and triggers an offset recalculation. Wire via a ResizeObserver on each rendered row.', 8, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('6ef91197-5d2e-4964-a081-f09aa73d6846', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '9ac6f6d7-4ade-483a-ab56-760faf0c086f', '(model)', 'Ref<TInnerVal<Inner>> & { readonly externalValue: Props[Prop] }', '', 'A writable computed ref. Reading it returns the current value (controlled or internal). Writing it updates the internal ref and emits `update:prop`. The `externalValue` accessor returns the raw prop value without transformIn applied.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('847b3dd3-6cca-4a97-aec7-f56ec82e7697', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'a5213afb-5e59-437a-9e12-20fc4b325b45', 'patternUrl', 'ComputedRef<string>', '', 'CSS `url("data:image/svg+xml,…")` string. Bind to `background-image` on any container element, or pass to `install()`. Recomputes reactively when options change.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('75647758-8379-4d5f-ac91-560fc3845e2c', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'a5213afb-5e59-437a-9e12-20fc4b325b45', 'install', '(target?: HTMLElement) => HTMLElement | null', '', 'Inject a full-cover `<div>` layer with `position: absolute; inset: 0` and the pattern as background-image into `target` (defaults to document.body). Sets `position: relative` on the target if it is `static`. Returns the created layer element, or null during SSR.', 1, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('acbf4d5b-8cc7-41df-a8f2-6a89d7239311', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', 'a5213afb-5e59-437a-9e12-20fc4b325b45', 'uninstall', '() => void', '', 'Remove the injected layer and disconnect the MutationObserver if active. Called automatically on scope dispose.', 2, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('099df95a-88ed-49fe-a7d8-93926419c4bd', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3f649435-2636-4099-8af0-1e554d6d28bb', 'peaks', 'Ref<Array<number>>', '', 'Array of `bins` values in [0, 1], where 1 is the loudest bucket in the track. Empty while computing or on error.', 0, false, NULL, NULL);
INSERT INTO public.doc_return (id, created_at, updated_at, entry_id, name, type, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('02568d0f-6753-4612-9441-1cec641712b8', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '3f649435-2636-4099-8af0-1e554d6d28bb', 'isComputing', 'Ref<boolean>', '', 'True while the fetch + decode round-trip is in progress. Use to render a skeleton or loading indicator.', 1, false, NULL, NULL);
