INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('f3945553-5244-43dd-a4bd-1786d53891a3', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '2f389d72-ac7e-41c2-9047-ac8d604234c6', 'sm', 'types.detail.empty_state_size.sm', 'Compact — smaller icon, reduced font sizes, tighter padding. Suitable for inline empty zones inside dense containers such as sidebars or data tables.', 1, false, NULL, NULL);
