INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('39b41b30-9108-4d62-9f8d-5410fd75f83c', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '2a02f2c4-6d5b-437c-ba9d-0c042cee8737', 'list', 'types.detail.file_field_display.list', 'Default. Renders each selected file as a card in a vertical stack below the field. Suitable when filenames and per-file actions (remove, download, progress) need to be visible.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('965f0b5f-86d4-4351-80c7-eb6894601f19', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '2a02f2c4-6d5b-437c-ba9d-0c042cee8737', 'chips', 'types.detail.file_field_display.chips', 'Renders each selected file as a closable <OrigamChip> inline inside the field. Compact mode — best for forms where many files can be selected but vertical space is limited.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('181b6b69-7dee-4724-a5ac-34c88cdc8bcf', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '2a02f2c4-6d5b-437c-ba9d-0c042cee8737', 'counter', 'types.detail.file_field_display.counter', 'Shows a single "N files selected" line with an <OrigamCounter>. Most compact mode — use when the file names are irrelevant to the user after selection.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('344fe019-360b-44ef-83b3-709ac8e1e90b', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '9e6bb574-b140-405e-b2d1-f3deb2b25e00', 'false', 'types.detail.file_size.false', 'File sizes are not displayed. This is the default behaviour when the showSize prop is omitted.', 0, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('1244b110-24bb-4e06-9368-788be010fd37', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '9e6bb574-b140-405e-b2d1-f3deb2b25e00', 'true', 'types.detail.file_size.true', 'File sizes are displayed using the SI divisor (1 000) — KB, MB, GB.', 1, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('e9947151-d161-47a0-9389-0d186defb7b0', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '9e6bb574-b140-405e-b2d1-f3deb2b25e00', '1000', 'types.detail.file_size.1000', 'Explicit SI (decimal) units: 1 KB = 1 000 bytes, 1 MB = 1 000 000 bytes. Matches the marketing convention used by most storage providers.', 2, false, NULL, NULL);
INSERT INTO public.doc_value (id, created_at, updated_at, entry_id, value, description_key, description_fallback, "position", edited_by_user, editorial_locked_at, orphaned_at) VALUES ('17419df4-f9c1-435a-8e36-70cb5434ba36', '2026-11-24 21:40:02.543053+00', '2026-11-24 21:40:02.543053+00', '9e6bb574-b140-405e-b2d1-f3deb2b25e00', '1024', 'types.detail.file_size.1024', 'Binary / IEC units: 1 KiB = 1 024 bytes, 1 MiB = 1 048 576 bytes. Traditional computing convention; more accurate for OS-reported file sizes.', 3, false, NULL, NULL);
